/* DAWAH X — ahmad, অধ্যায় 71 · খণ্ড 71 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][71]=[[14001,14001,"","আমরা একজন পরিদর্শনকারীর কথা বলেছিলাম, আমরা তার বাবার সবচেয়ে ভাল কথা বলেছিলাম, ঈশ্বর এটা উদ্ধার করতে হবে যদি তারা দেখে যে তুমি তোমার মুখ জয় করতে পারবে।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَأَيْتُمْ الْهِلَالَ فَصُومُوا وَإِذَا رَأَيْتُمُوهُ فَأَفْطِرُوا فَإِنْ ‏ ‏غُمَّ ‏ ‏عَلَيْكُمْ فَعُدُّوا ثَلَاثِينَ يَوْمًا ‏","","",""],[14002,14002,"","আমরা একজন পরিদর্শনকারীর কথা বলেছিলাম, আমরা তার শ্বশুর আব্বার কথা বলেছিলাম, সে তার মাথা থেকে এক মাস দূরে চলে যাবে, আর সে এই কাজে আসবে আর ছেলেটির অবতরণের মাঝে থাকবে, প্রভু, আপনি এক রাতের বেশী করেছেন বলে বলতে যে ঈশ্বর তাকে প্রার্থনা করছেন। এবং তিনি দুইবার তার হাত ধরে চুমু খাওয়ান এবং তিন টায় আমি শুনতে হবে. যাবেষের হয়তো বলতে পারে যে ঈশ্বর ভাববাদীকে বের করে তার মেয়েকে ভাল উপায়ে দিয়ে যাচ্ছেন।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرًا ‏ ‏يَقُولُ ‏ ‏هَجَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِسَاءَهُ شَهْرًا فَكَانَ يَكُونُ فِي الْعُلْوِ وَيَكُنَّ فِي السُّفْلِ فَنَزَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيْهِنَّ فِي تِسْعٍ وَعِشْرِينَ لَيْلَةً فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ إِنَّكَ مَكَثْتَ تَسْعًا وَعِشْرِينَ لَيْلَةً فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الشَّهْرَ هَكَذَا وَهَكَذَا بِأَصَابِعِ يَدِهِ مَرَّتَيْنِ وَقَبَضَ فِي الثَّالِثَةِ إِبْهَامَهُ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏اعْتَزَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِسَاءَهُ شَهْرًا ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[14003,14003,"","আমরা আমাদের কস্টিউমের কথা বলেছিলাম, সে ওকে দেশ থেকে আত্মসমর্পণ করতে বলেছে... ...যে মানুষের এই কল্পনার জন্য সে তার উপর নির্ভর করেছে. হত্যা এবং তার আলোচনা শুরু করা হয়েছে। আমার বিশ্বাস তুমি প্রভুর দিনে নয়, আর ঈশ্বরের বার্তাবাহকের কথা শোনো। আমাদের সাথে আছেন এমন এক যুবকের বাবা, ঈশ্বর কিছু অজুহাত দিয়েছেন, আর তারপর আমরা তার সাথে কথা বলি। সে মানুষের কাছে গিয়ে জানতে চায় সে কুখ্যাত নয়।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةٍ غَزَاهَا وَذَلِكَ فِي رَمَضَانَ فَصَامَ رَجُلٌ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَضَعُفَ ضَعْفًا شَدِيدًا وَكَادَ الْعَطَشُ أَنْ يَقْتُلَهُ وَجَعَلَتْ نَاقَتُهُ تَدْخُلُ تَحْتَ ‏ ‏الْعِضَاهِ ‏ ‏فَأُخْبِرَ بِهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ائْتُونِي بِهِ فَأُتِيَ بِهِ فَقَالَ ‏ ‏أَلَسْتَ فِي سَبِيلِ اللَّهِ وَمَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْطِرْ فَأَفْطَرَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَابِقٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ طَهْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏صَامَ رَجُلٌ مِنَّا وَنَحْنُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ مَغَازِيهِ فَذَكَرَ مَعْنَاهُ قَالَ ثُمَّ دَعَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَدَحٍ فَرَفَعَهُ عَلَى يَدَيْهِ فَشَرِبَ لِيَرَى النَّاسُ أَنَّهُ لَيْسَ بِصَائِمٍ ‏","","",""],[14004,14004,"","আমরা কথা বলেছিলাম একটা পিপপি পুত্র নিয়ে আমাকে বললো ক্যাপ্টেন আমাকে বললেন যে ক্যাপ্টেন আমাকে এটা দিতে বলেছেন আর আমি চাই একটা গান দেখাতে আর তোমাকে কার সাথে শুরু করতে ভালো করে বাজাও।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْضَلُ ‏ ‏الصَّدَقَةِ ‏ ‏عَنْ ‏ ‏ظَهْرِ غِنًى ‏ ‏وَابْدَأْ بِمَنْ ‏ ‏تَعُولُ ‏ ‏وَالْيَدُ الْعُلْيَا خَيْرٌ مِنْ الْيَدِ السُّفْلَى ‏","","",""],[14005,14005,"","আমরা আমাদের বাবার জীবনের সবচেয়ে ভাল দিক নিয়ে কথা বলেছি, পরের কয়েক বছর আমার বাবার ইচ্ছা সম্পর্কে। ঈশ্বর তার মৃত্যুর আগে বলে দেবেন, যেন কেউ না মরে যায়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَبْلَ مَوْتِهِ بِثَلَاثٍ يَقُولُ ‏ ‏لَا يَمُوتَنَّ أَحَدُكُمْ إِلَّا وَهُوَ يُحْسِنُ بِاللَّهِ الظَّنَّ ‏","","",""],[14006,14006,"","আমরা কথা বলেছি যে আমি কতটা ভালবাসি, ঈশ্বর বলেছেন যে তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন তাকে উদ্ধার করতে আর তার যাত্রা সম্পন্ন করতে হবে। আমরা এখন নিচে আছি। আমরা বলছি, আমরা কি করবো? চুমু খেতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى رَاحِلَتِهِ نَحْوَ الْمَشْرِقِ فَإِذَا أَرَادَ أَنْ يُصَلِّيَ الْمَكْتُوبَةَ نَزَلَ فَاسْتَقْبَلَ الْقِبْلَةَ ‏","","",""],[14007,14007,"","আমি আমার কাছে শপথ করে বলছি যে, আমি একজন কঠিন ছেলের ছেলে। আমাকে বলা হয়েছে, আমি একজন জিনিয়াস। ঈশ্বর তার কাছে প্রতিজ্ঞা করেছেন যে তিনি হলেন তার কাছে প্রতিজ্ঞা করেছেন। আমি ঈশ্বরের কাছে নিজেকে সমর্পণ করছি, ঈশ্বরের কাছে আমার শপথ করতে হবে যে আমি তোমাকে বলব না, আমি আমার কাছে তোমার কাছে পড়তে চাই, আমি এটা করব, তারা মাতাল ছিল, কিন্তু তারা ছিল যাও যাও গিয়ে যাও, ঈশ্বর তার কাছে প্রার্থনা করো আর সে বলবে আগুন থেকে বের হয়ে যাও... ...আর আমরা সিদ্ধান্ত নেব তুমি যা পড়.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏الْقَاسِمُ يَعْنِي ابْنَ الْفَضْلِ وَهُوَ الْحُدَّانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ الْمُهَلَّبِ ‏ ‏عَنْ ‏ ‏طَلْقِ بْنِ حَبِيبٍ ‏ ‏قَالَ ‏ ‏كُنْتُ مِنْ أَشَدِّ النَّاسِ تَكْذِيبًا بِالشَّفَاعَةِ حَتَّى لَقِيتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏فَقَرَأْتُ عَلَيْهِ كُلَّ آيَةٍ ذَكَرَهَا اللَّهُ عَزَّ وَجَلَّ فِيهَا خُلُودُ أَهْلِ النَّارِ فَقَالَ يَا ‏ ‏طَلْقُ ‏ ‏أَتُرَاكَ أَقْرَأَ لِكِتَابِ اللَّهِ مِنِّي وَأَعْلَمَ بِسُنَّةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاتُّضِعْتُ ‏ ‏لَهُ فَقُلْتُ لَا وَاللَّهِ بَلْ أَنْتَ أَقْرَأُ لِكِتَابِ اللَّهِ مِنِّي وَأَعْلَمُ بِسُنَّتِهِ مِنِّي قَالَ فَإِنَّ الَّذِي قَرَأْتَ أَهْلُهَا هُمْ الْمُشْرِكُونَ وَلَكِنْ قَوْمٌ أَصَابُوا ذُنُوبًا فَعُذِّبُوا بِهَا ثُمَّ أُخْرِجُوا صُمَّتَا وَأَهْوَى بِيَدَيْهِ إِلَى أُذُنَيْهِ إِنْ لَمْ أَكُنْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَخْرُجُونَ مِنْ النَّارِ وَنَحْنُ نَقْرَأُ مَا تَقْرَأُ ‏","","",""],[14008,14008,"","আমরা বধির এবং আমাদের অনেক আগে ঘটেছে সম্পর্কে কথা বলেছি। ঈশ্বর ঈশ্বর আমার বাবাকে অনেক কিছু দিতে বলেছেন। অন্য রাতে, বিশ্বাস করো, তোমার শক্তি নেয়ার মত বয়স তোমার।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَمُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَبِي بَكْرٍ ‏ ‏أَيَّ حِينٍ ‏ ‏تُوتِرُ ‏ ‏قَالَ أَوَّلَ اللَّيْلِ بَعْدَ ‏ ‏الْعَتَمَةِ ‏ ‏قَالَ فَأَنْتَ يَا ‏ ‏عُمَرُ ‏ ‏قَالَ آخِرَ اللَّيْلِ فَقَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّا أَنْتَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَأَخَذْتَ ‏ ‏بِالْوُثْقَى ‏ ‏وَأَمَّا أَنْتَ يَا ‏ ‏عُمَرُ ‏ ‏فَأَخَذْتَ بِالْقُوَّةِ ‏","","",""],[14009,14009,"","আমরা বধির আর বাবার সাথে কথা বলেছি, সে আমাদের ধুকে মেরে ফেলেছে আর আমরা এটা করেছি, আর আমরা তাকে ভুল বলে ডাকতে পারবো। সে বলেছিল সে তাকে মেরে ফেলবে. ঈশ্বর এই কাজে ব্যয় করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَأَبُو سَعِيدٍ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏تُوُفِّيَ رَجُلٌ فَغَسَّلْنَاهُ وَحَنَّطْنَاهُ وَكَفَّنَّاهُ ثُمَّ أَتَيْنَا بِهِ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَيْهِ فَقُلْنَا تُصَلِّي عَلَيْهِ فَخَطَا خُطًى ثُمَّ قَالَ ‏ ‏أَعَلَيْهِ دَيْنٌ قُلْنَا دِينَارَانِ فَانْصَرَفَ فَتَحَمَّلَهُمَا ‏ ‏أَبُو قَتَادَةَ ‏ ‏فَأَتَيْنَاهُ فَقَالَ ‏ ‏أَبُو قَتَادَةَ ‏ ‏الدِّينَارَانِ عَلَيَّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُحِقَّ ‏ ‏الْغَرِيمُ ‏ ‏وَبَرِئَ مِنْهُمَا الْمَيِّتُ قَالَ نَعَمْ فَصَلَّى عَلَيْهِ ثُمَّ قَالَ بَعْدَ ذَلِكَ بِيَوْمٍ مَا فَعَلَ الدِّينَارَانِ فَقَالَ إِنَّمَا مَاتَ أَمْسِ قَالَ فَعَادَ إِلَيْهِ مِنْ الْغَدِ فَقَالَ لَقَدْ قَضَيْتُهُمَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْآنَ بَرَدَتْ عَلَيْهِ جِلْدُهُ ‏ ‏فَقَالَ ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏فِي هَذَا الْحَدِيثِ فَغَسَّلْنَاهُ وَقَالَ فَقُلْنَا نُصَلِّي عَلَيْهِ ‏","","",""],[14010,14010,"","আমার সাথে যা ঘটেছে তার কথা বলেছিলাম, যে যুদ্ধ আমার বাবার ছেলে তার বাবার জন্য। আমি ঈশ্বরের কাছে প্রার্থনা করবো আর তাকে একটা গুলি করে দেবো। সে বলেছে যে একজন মহিলাকে শয়তানের ছবিতে আটকে রাখা হয়েছে আর তার উপর কিছু একটার জন্য চেষ্টা করা হচ্ছে, তাই আমি তোমাকে দেখতে পাচ্ছি, সে চায় সে শ্বাস নিতে চায়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏حَرْبٌ يَعْنِي ابْنَ أَبِي الْعَالِيَةِ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى امْرَأَةً فَأَعْجَبَتْهُ فَأَتَى ‏ ‏زَيْنَبَ ‏ ‏وَهِيَ ‏ ‏تَمْعَسُ ‏ ‏مَنِيئَةً ‏ ‏فَقَضَى مِنْهَا حَاجَتَهُ وَقَالَ ‏ ‏إِنَّ الْمَرْأَةَ تُقْبِلُ فِي صُورَةِ شَيْطَانٍ ‏ ‏وَتُدْبِرُ ‏ ‏فِي صُورَةِ شَيْطَانٍ فَإِذَا رَأَى أَحَدُكُمْ امْرَأَةً فَأَعْجَبَتْهُ فَلْيَأْتِ أَهْلَهُ فَإِنَّ ذَاكَ يَرُدُّ مِمَّا فِي نَفْسِهِ ‏","","",""],[14011,14011,"","ঈশ্বর আমার এই আস্থা রয়েছে যে, ভাববাদী তার অকালমৃত্যুর জন্য প্রার্থনা করবেন । \"বাদামে,\" \"এখান থেকে চলে গেছে, আর সবকিছু ঘটেছে না হওয়া পর্যন্ত।\" সিনব তাকে ঐ কলমে খুন করে যেখানে তাকে সূর্য স্পর্শ করতে হয় এবং তারপর তাকে যেতে হয় ডিনারে যখন বৃষ্টি শুরু হয়, তখন বিস্ফোরণটা বলে, যখন তা উড়িয়ে দেয়, তখন সেটা কম করে কেটে দেয় । একা, আর সে চলে যায়নি আর সে যখন চলে গেল, ডিনারে চলে গিয়েছিল, ডিনারটা উড়ে গিয়েছিল, যখন আমি দুঃখিত, সে বলেছিল সে চলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏حُسَيْنِ بْنِ عَلِيٍّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏وَهْبُ بْنُ كَيْسَانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ وَهُوَ الْأَنْصَارِيُّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَهُ ‏ ‏جِبْرِيلُ ‏ ‏فَقَالَ قُمْ ‏ ‏فَصَلِّهْ ‏ ‏فَصَلَّى الظُّهْرَ حِينَ ‏ ‏زَالَتْ الشَّمْسُ ‏ ‏ثُمَّ جَاءَهُ الْعَصْرَ فَقَالَ قُمْ ‏ ‏فَصَلِّهْ فَصَلَّى الْعَصْرَ حِينَ صَارَ ظِلُّ كُلِّ شَيْءٍ مِثْلَهُ ‏ ‏أَوْ قَالَ صَارَ ظِلُّهُ مِثْلَهُ ‏ ‏ثُمَّ جَاءَهُ الْمَغْرِبَ فَقَالَ قُمْ ‏ ‏فَصَلِّهْ فَصَلَّى حِينَ وَجَبَتْ الشَّمْسُ ثُمَّ جَاءَهُ الْعِشَاءَ فَقَالَ قُمْ ‏ ‏فَصَلِّهْ فَصَلَّى حِينَ غَابَ ‏ ‏الشَّفَقُ ‏ ‏ثُمَّ جَاءَهُ الْفَجْرَ فَقَالَ قُمْ ‏ ‏فَصَلِّهْ فَصَلَّى حِينَ ‏ ‏بَرَقَ ‏ ‏الْفَجْرُ ‏ ‏أَوْ قَالَ حِينَ سَطَعَ الْفَجْرُ ‏ ‏ثُمَّ جَاءَهُ مِنْ الْغَدِ لِلظُّهْرِ فَقَالَ قُمْ ‏ ‏فَصَلِّهْ فَصَلَّى الظُّهْرَ حِينَ صَارَ ظِلُّ كُلِّ شَيْءٍ مِثْلَهُ ثُمَّ جَاءَهُ لِلْعَصْرِ فَقَالَ قُمْ ‏ ‏فَصَلِّهْ فَصَلَّى الْعَصْرَ حِينَ صَارَ ظِلُّ كُلِّ شَيْءٍ مِثْلَيْهِ ثُمَّ جَاءَهُ لِلْمَغْرِبِ الْمَغْرِبَ وَقْتًا وَاحِدًا لَمْ يَزُلْ عَنْهُ ثُمَّ جَاءَ لِلْعِشَاءِ الْعِشَاءَ حِينَ ذَهَبَ نِصْفُ اللَّيْلِ ‏ ‏أَوْ قَالَ ثُلُثُ ‏ ‏اللَّيْلِ ‏ ‏فَصَلَّى الْعِشَاءَ ثُمَّ جَاءَهُ لِلْفَجْرِ حِينَ ‏ ‏أَسْفَرَ ‏ ‏جِدًّا فَقَالَ قُمْ ‏ ‏فَصَلِّهْ فَصَلَّى الْفَجْرَ ثُمَّ قَالَ مَا بَيْنَ هَذَيْنِ وَقْتٌ ‏","","",""],[14012,14012,"","আমরা কয়েকদিন বেঁচে থাকার চেষ্টা করেছি, কিন্তু আমরা আমার ভাইয়ের চেয়ে ভালো আছি। ভাস্কর্যের ভাস্কর্যের ভাস্কর্যের ভাস্কর্যের জন্য শোকাচ্ছন্ন। ভাস্কর্যের ভাস্কর্য, যখন তিনি \"ফাঁ\" বলেছিলেন","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ عَيَّاشٍ أَخُو أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُصَلِّي الْجُمُعَةَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ نَرْجِعُ فَنُرِيحُ ‏ ‏نَوَاضِحَنَا ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏قُلْتُ ‏ ‏لِجَعْفَرٍ ‏ ‏وَمَتَى ذَاكَ قَالَ ‏ ‏زَوَالَ الشَّمْسِ ‏","","",""],[14013,14013,"","আমরা আমার বাবার ব্যাপারে কথা বলেছি, আমরা তার ছেলের উত্তর নিয়ে কথা বলেছি, সে আত্মসমর্পণ করেছে, যদি তুমি তাকে মেরে ফেল, সে তিন বার বরফ হয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏قُطْبَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏أَجْمَرْتُمْ ‏ ‏الْمَيِّتَ ‏ ‏فَأَجْمِرُوهُ ‏ ‏ثَلَاثًا ‏","","",""],[14014,14014,"","আমরা একটা ছেলেকে রক্ষা করতে চেয়েছিলাম যে আমাকে পরাজিত করবে... ...কিন্তু ঈশ্বরের অনুগ্রহ... ...যে অন্ধকারের মধ্যে আছে... ...যে আমরা প্রভুর বার্তাবাহকের কাছে প্রার্থনা করি। তারপর আমরা আমার ছেলেকে সেখানে পৌঁছে দিয়ে যাবো, আর এটা দুই মাইল দূরে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏وَأَبُو أَحْمَدَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ يَزِيدَ الْأَنْصَارِيُّ ‏ ‏قَالَ ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنِي ‏ ‏عُقْبَةُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُصَلِّي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْجُمُعَةَ ثُمَّ نَرْجِعُ ‏ ‏فَنَقِيلُ ‏ ‏قَالَ ‏ ‏أَبُو أَحْمَدَ ‏ ‏ثُمَّ نَرْجِعُ إِلَى ‏ ‏بَنِي سَلِمَةَ ‏ ‏فَنَقِيلُ ‏ ‏وَهُوَ عَلَى مِيلَيْنِ ‏","","",""],[14015,14015,"","আমরা বাবার সঙ্গে প্রেম দেখানোর চেষ্টা করার সময় মারা যাওয়ার কথা বলেছিলাম । হালকা আলোর আলো হালকা করে আলোর আলোক আলোক আলোক আলোক আলোকের আলোককে আলো হিসেবে হালকা করে আলোর আলোর আলো বলে ; তিনি রাজার হাতে যে জ্যোতির আলো দিয়েছেন, তার আলো","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُصَلِّي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَغْرِبَ ثُمَّ نَرْجِعُ إِلَى ‏ ‏بَنِي سَلِمَةَ ‏ ‏فَنَرَى مَوَاقِعَ النَّبْلِ ‏","","",""],[14016,14016,"","আমরা আমার বাবাকে রক্ষা করার বিষয়ে বলেছিলাম যে তিনি কখনো তা বলেননি ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُبْعَثُ كُلُّ عَبْدٍ عَلَى مَا مَاتَ عَلَيْهِ ‏","","",""],[14017,14017,"","সে ঈশ্বরের কাছে প্রার্থনা করলো... ...আর আজ রাতে সে আমাকে সমর্পণ করবে... ...যেন সে স্বপ্নের মত হতে না পারে, আমি তাকে দিয়ে দেই আর প্রতি রাতে সে থাকে.","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ فِي اللَّيْلِ لَسَاعَةً لَا يُوَافِقُهَا عَبْدٌ مُسْلِمٌ يَسْأَلُ اللَّهَ فِيهَا شَيْئًا إِلَّا أَعْطَاهُ إِيَّاهُ وَهِيَ فِي كُلِّ لَيْلَةٍ ‏","","",""],[14018,14018,"","তিনি এবং লোকেরা ভাল ও মন্দের জন্য হাঙ্গর বিক্রি করবে বলে তার কাছে আছে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّاسُ تَبَعٌ ‏ ‏لِقُرَيْشٍ ‏ ‏فِي الْخَيْرِ وَالشَّرِّ ‏","","",""],[14019,14019,"","আমরা বাবা বা বাবার সাথে কথা বলেছি, আমরা ঈশ্বরের ছেলের সাথে থাকার কথা বলেছিলাম, সে নীরব মানুষ উদ্ধার করবে আর সে গর্ভের মধ্যে থাকবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى أَنْ ‏ ‏يَشْتَمِلَ ‏ ‏الرَّجُلُ ‏ ‏الصَّمَّاءَ ‏ ‏وَأَنْ ‏ ‏يَحْتَبِيَ ‏ ‏فِي الثَّوْبِ الْوَاحِدِ لَيْسَ عَلَى فَرْجِهِ مِنْهُ شَيْءٌ ‏","","",""],[14020,14020,"","আমরা সমকামীদের সাথে কথা বলেছি আমার বাবার সাথে গ্রেসের ব্যাপারে কথা বলেছে, ঈশ্বর আমাকে বলতে দিন।","‏ ‏حَدَّثَنَا ‏ ‏شَاذَانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَأَى مَا فُسِحَ لَهُ فِي قَبْرِهِ يَقُولُ دَعُونِي أُبَشِّرُ أَهْلِي فَيُقَالُ لَهُ اسْكُنْ ‏","","",""],[14021,14021,"","বাবা আমাকে কি ভালবাসতে চাচ্ছেন আমরা কথা বলেছি, ঈশ্বরের ইচ্ছা ছিল তার কাছে প্রার্থনা করা এবং তিনি ঈশ্বরের কাছে প্রার্থনা করব তিনি তার কাছে প্রার্থনা করবেন. আর যখন তুমি চলে যাবে তখন উজ্জ্বল স্বাদের স্বাদ আসবে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مَيْمُونٍ أَبُو النَّضْرِ الزَّعْفَرَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏مَتَى كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الْجُمُعَةَ فَقَالَ ‏ ‏كُنَّا ‏ ‏نُصَلِّيهَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ نَرْجِعُ فَنُرِيحُ ‏ ‏نَوَاضِحَنَا ‏ ‏قَالَ ‏ ‏جَعْفَرٌ ‏ ‏وَإِرَاحَةُ ‏ ‏النَّوَاضِحِ ‏ ‏حِينَ ‏ ‏تَزُولُ الشَّمْسُ ‏","","",""],[14022,14022,"","আমরা একটা নিশ্চিত মেমোন সম্পর্কে কথা বলেছিলাম যে আমার বাবার কাছে ঈশ্বরের অনুগ্রহের জন্য নিয়ে এসেছিল, ঈশ্বরের শান্তি ছিল শত বছর আগে, তার হাত দিয়ে, আর সে তিন বার মুক্ত হয়ে গেছে। কয়েক বার তাকে একটা টর মধ্যে দিয়ে দেওয়া হয় এবং এরপর তার অতীত থেকে পান করা হয় ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مَيْمُونٍ ‏ ‏حَدَّثَنِي ‏ ‏جَعْفَرٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ ‏ ‏الْبُدْنَ ‏ ‏الَّتِي ‏ ‏نَحَرَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَتْ مِائَةَ ‏ ‏بَدَنَةٍ ‏ ‏نَحَرَ ‏ ‏بِيَدِهِ ثَلَاثًا وَسِتِّينَ ‏ ‏وَنَحَرَ ‏ ‏عَلِيٌّ ‏ ‏مَا ‏ ‏غَبَرَ ‏ ‏وَأَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ كُلِّ ‏ ‏بَدَنَةٍ ‏ ‏بِبَضْعَةٍ فَجُعِلَتْ فِي قِدْرٍ ثُمَّ شَرِبَا مِنْ مَرَقِهَا ‏","","",""],[14023,14023,"","আমরা বাবা বা বাবার সাথে কথা বলেছি, আমরা দুই ছেলেকে খুনীর সাথে লড়াই করার চেষ্টা করেছি, ঈশ্বর তাকে শিখিয়েছেন আর সে আপনার ইচ্ছার একজন মহিলা, যে আমার বাবার মনের ভিতরে চলে গেছে সে তখন করতে রাজি ছিল, আল্লাহ তোমাকে দয়া করে, অপরাধীর লোকদের আশীর্বাদ করো, আর তারপর সে বলেছিল সে তার আত্মা ছেড়ে দেবে। সে আমার বাবা-মাকে বলে যে তুমি তাকে ভেতরে নিয়ে যাবে। আমি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ امْرَأَةٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏صَنَعَتْ لَهُ طَعَامًا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْخُلُ عَلَيْكُمْ رَجُلٌ مِنْ أَهْلِ الْجَنَّةِ فَدَخَلَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَهَنَّيْنَاهْ ثُمَّ قَالَ يَدْخُلُ عَلَيْكُمْ رَجُلٌ مِنْ أَهْلِ الْجَنَّةِ فَدَخَلَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَهَنَّيْنَاهْ ثُمَّ قَالَ يَدْخُلُ عَلَيْكُمْ رَجُلٌ مِنْ أَهْلِ الْجَنَّةِ فَرَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُدْخِلُ رَأْسَهُ تَحْتَ ‏ ‏الْوَدِيِّ ‏ ‏فَيَقُولُ اللَّهُمَّ إِنْ شِئْتَ جَعَلْتَهُ ‏ ‏عَلِيًّا ‏ ‏فَدَخَلَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَهَنَّيْنَاهْ ‏","","",""],[14024,14024,"","আমরা ঈশ্বরের প্রেম নিয়ে কথা বলেছি যখন আমরা ঈশ্বরের প্রেম নিয়ে কথা বলেছিলাম, প্রভু তাঁর জন্য প্রার্থনা করেছেন এবং প্রভুর ভয় এবং আত্মার আত্মার ভয়কে রক্ষা করেছেন আর প ্ রত ্ যেক সত ্ ত ্ বা জানে যা সে অর ্ জন করেছে তার জন ্ য , আর তার অন ্ তর আছে ন ্ যায়সঙ ্ গত । আত্মার আত্মার আত্মার আত্মারপ্রাণপ্রাণের কাজ, আর এটা আত্মার আত্মার আত্মার আত্মার আত্মার ফলের একটা দিকও নেই ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏وَعَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَيْرُ صُفُوفِ الرِّجَالِ الْمُقَدَّمُ وَشَرُّهَا الْمُؤَخَّرُ وَخَيْرُ صُفُوفِ النِّسَاءِ الْمُؤَخَّرُ وَشَرُّهَا الْمُقَدَّمُ ‏","","",""],[14025,14025,"","বাবা বলেছিলেন, তিনি ভগবানকে ফোন করেছিলেন, যদি সে এক হাত পড়ে যায়, সে এটা করেনি। আমি তার কাছে যাচ্ছি, সে জানে না তার মহিমা কী।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَقَطَتْ اللُّقْمَةُ مِنْ يَدِ أَحَدِكُمْ ‏ ‏فَلْيُمِطْ ‏ ‏مَا كَانَ عَلَيْهَا مِنْ الْأَذَى وَلَا يَدَعْهَا لِلشَّيْطَانِ وَلَا يَمْسَحْ يَدَهُ بِالْمِنْدِيلِ وَلْيَلْعَقْ أَصَابِعَهُ فَإِنَّهُ لَا يَدْرِي فِي أَيِّ ‏ ‏طَعَامِهِ الْبَرَكَةُ ‏","","",""],[14026,14026,"","বাবা আমরা কথা বলেছি তার আনন্দশক্তির জন্য আমরা ঈশ্বরকে পেতে চাই। আমার উপত্যকায় ছুরি অথবা এটা রেখে দিন। যেমন আমি দেখতে পাচ্ছি, এই ক্ষুদ্র-অ-বাধী-অ-অ-প্রতিযোগী, আমি নই। ওদের শেষ হওয়ার পর তাদের সাথে দেখা করবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏دَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْهِ ‏ ‏السَّكِينَةُ ‏ ‏وَأَوْضَعَ فِي ‏ ‏وَادِي مُحَسِّرٍ ‏ ‏فَأَرَاهُمْ مِثْلَ حَصَى ‏ ‏الْخَذْفِ ‏ ‏وَأَمَرَهُمْ ‏ ‏بِالسَّكِينَةِ ‏ ‏وَقَالَ لِتَأْخُذْ أُمَّتِي مَنْسَكَهَا فَإِنِّي لَا أَدْرِي لَعَلِّي لَا أَلْقَاهُمْ بَعْدَ عَامِهِمْ هَذَا ‏","","",""],[14027,14027,"","আমরা বাবার সাথে কথা বলেছি যে ঈশ্বর তাকে আনতে চেষ্টা করছেন, আমি হ্রদটা করতে যাচ্ছি না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَرْشُ إِبْلِيسَ عَلَى الْبَحْرِ يَبْعَثُ ‏ ‏سَرَايَاهُ ‏ ‏فَأَعْظَمُهُمْ عِنْدَهُ مَنْزِلَةً أَعْظَمُهُمْ ‏ ‏فِتْنَةً ‏","","",""],[14028,14028,"","বাবা - মা আমাদের বলেছিলেন যে, আমাদের দুজন ছেলে তার কাছে এসেছিল । আর তাই আমি প্রার্থনা করছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏بَعَثَنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَاجَةٍ فَجِئْتُ وَهُوَ ‏ ‏يُصَلِّي عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏نَحْوَ الْمَشْرِقِ ‏ ‏وَيُومِئُ ‏ ‏إِيمَاءً ‏ ‏السُّجُودُ أَخْفَضُ مِنْ الرُّكُوعِ فَسَلَّمْتُ عَلَيْهِ فَلَمَّا انْصَرَفَ قَالَ مَا فَعَلْتَ فِي حَاجَةِ كَذَا وَكَذَا إِنِّي كُنْتُ أُصَلِّي ‏","","",""],[14029,14029,"","ঈশ্বর যদি আমাদের তাঁর ঘর থেকে বের করে দেন, তা হলে আমরা আপনার ছায়াতে চলে যাব ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏نُبَيْحٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا خَرَجَ مِنْ بَيْتِهِ مَشَيْنَا قُدَّامَهُ وَتَرَكْنَا ظَهْرَهُ لِلْمَلَائِكَةِ ‏","","",""],[14030,14030,"","তিনি বলেছিলেন, ঈশ্বর তাঁর জন্য প্রার্থনা করবেন এবং সেই বাঁধকে তিনি তার আশীর্বাদ দেবেন এবং তিনি তা করবেন । সাহায্য আর সুস্থ হওয়ার পর বাবা বলেছিলেন, এগুলো ভদ্রভাবে বই।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةُ ‏ ‏يَتْرُكُهَا أَهْلُهَا وَهِيَ ‏ ‏مُرْطِبَةٌ ‏ ‏قَالُوا فَمَنْ يَأْكُلُهَا يَا رَسُولَ اللَّهِ قَالَ السِّبَاعُ ‏ ‏وَالْعَائِفُ ‏ ‏قَالَ ‏ ‏أَبُو عَوَانَةَ ‏ ‏فَحُدِّثْتُ أَنَّ ‏ ‏أَبَا بِشْرٍ ‏ ‏قَالَ ‏ ‏كَانَ فِي كِتَابِ ‏ ‏سُلَيْمَانَ بْنِ قَيْسٍ ‏","","",""],[14031,14031,"","আমরা আমার বাবার কথা বলেছিলাম, সে কিভাবে প্রেমে পড়লো সে বলবে সে সাহস নিয়ে ঠিক আছে, আর সে জেগে উঠবে আর জনতার মাঝে শুকিয়ে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْإِيمَانُ فِي أَهْلِ ‏ ‏الْحِجَازِ ‏ ‏وَغِلَظُ الْقُلُوبِ ‏ ‏وَالْجَفَاءُ ‏ ‏فِي ‏ ‏الْفَدَّادِينَ ‏ ‏فِي أَهْلِ الْمَشْرِقِ ‏","","",""],[14032,14032,"","বাবা যখন আমার ছেলে ছিল, তখন আমার বাবার সাথে কথা বলেছিলাম, ঈশ্বর তাকে দাবি করেছেন আর তাকে উদ্ধার করেছেন যারা মানুষকে সৌভাগ্যের অতীত থেকে তিন বার যেতে দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَسِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَرَكَ الْجُمُعَةَ ثَلَاثَ مِرَارٍ مِنْ غَيْرِ عُذْرٍ طَبَعَ اللَّهُ عَلَى قَلْبِهِ ‏","","",""],[14033,14033,"","আমি প্রার্থনা করি, আল্লাহ আমাকে মুক্তি দিয়েছেন এবং আমি মানুষকে খুন করার আদেশ দিয়েছি যাতে তারা আমাকে না বলে। আমি এটা করতে যাচ্ছি.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏ح ‏ ‏وَأَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا لَا إِلَهَ إِلَّا اللَّهُ فَإِذَا قَالُوهَا ‏ ‏عَصَمُوا ‏ ‏مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ وَأَنْفُسَهُمْ إِلَّا بِحَقِّهَا وَحِسَابُهُمْ عَلَى اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[14034,14034,"","আমরা কথা বলেছিলাম, কিভাবে হারটা দেয়ালের ওপর একটা পিন দিয়ে পার হয়ে গেল, ঈশ্বরের কসম করে বলছি, সে শপথ করে কসম করে বলবে যে, সে তাকে মেরে ফেলবে যদি সে একজন লোককে মেরে ফেলে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ العَقَدِىُّ ‏ ‏حَدَّثَنَا ‏ ‏قُرَّةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏بَيْنَمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْسِمُ مَغَانِمَ ‏ ‏حُنَيْنٍ ‏ ‏إِذْ قَامَ إِلَيْهِ ‏ ‏رَجُلٌ ‏ ‏فَقَالَ اعْدِلْ فَقَالَ لَقَدْ شَقِيتُ إِنْ لَمْ أَعْدِلْ ‏","","",""],[14035,14035,"","ঈশ্বর তাকে প্রভাবিত করার চেষ্টা করছেন এমন একজন দেবীর এক পুত্র আমাদের সঙ্গে কথা বলার সময় আমাদের বাবার সঙ্গে কথা বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ مُحَمَّدِ بْنِ طَحْلَاءَ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ أَبِي حَيَّانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏تَوَلَّى ‏ ‏غَيْرَ ‏ ‏مَوَالِيهِ ‏ ‏فَقَدْ خَلَعَ ‏ ‏رِبْقَةَ ‏ ‏الْإِيمَانِ مِنْ عُنُقِهِ ‏","","",""],[14036,14036,"","আমরা অনেক আগেই কথা বলেছি, একটা কুকুরের বাচ্চা যে আমাকে রক্ষা করতে চেয়েছিল, তার মানে হল সে হয়তো তার জন্য প্রার্থনা করতে পারে আর সে তিন সন্তানের জন্য একটা ফোন করবে. গৌরবের মুখে শয়তানটাকে জানার জন্য, আমি তাকে ফোন করব!","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏كَثِيرٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ كَعْبِ بْنِ مَالِكٍ ‏ ‏حَدَّثَنِي ‏ ‏جَابِرٌ يَعْنِي ابْنَ عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعَا فِي مَسْجِدِ الْفَتْحِ ثَلَاثًا يَوْمَ ‏ ‏الِاثْنَيْنِ وَيَوْمَ الثُّلَاثَاءِ وَيَوْمَ الْأَرْبِعَاءِ فَاسْتُجِيبَ لَهُ يَوْمَ الْأَرْبِعَاءِ بَيْنَ الصَّلَاتَيْنِ فَعُرِفَ الْبِشْرُ فِي وَجْهِهِ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏فَلَمْ يَنْزِلْ بِي أَمْرٌ مُهِمٌّ غَلِيظٌ إِلَّا ‏ ‏تَوَخَّيْتُ ‏ ‏تِلْكَ السَّاعَةَ ‏ ‏فَأَدْعُو فِيهَا فَأَعْرِفُ الْإِجَابَةَ ‏","","",""],[14037,14037,"","আমরা একটি জীবনকথা বলেছি এবং বাবা আমাদের বলেছেন, এই পদক্ষেপ আমার বাবার কাছে অনেক বেশী বলে মনে হয়েছে। আমি শুনেছি জাবের বানের কাছে আমি হয়ত বলতে পারি যে ঈশ্বর এটা দিয়েছেন এবং তিনি তা দিয়েছেন। এটা একটা ভালো বুদ্ধি যে আগুন আর লর্ডের মধ্যে দিয়ে যেতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏وَأَبُو أَحْمَدَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏الْحَارِثُ بْنُ يَزِيدَ ‏ ‏قَالَ ‏ ‏أَبُو أَحْمَدَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ أَبِي يَزِيدَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَمَنَّوْا الْمَوْتَ فَإِنَّ هَوْلَ الْمَطْلَعِ شَدِيدٌ وَإِنَّ مِنْ السَّعَادَةِ أَنْ يَطُولَ عُمْرُ الْعَبْدِ وَيَرْزُقَهُ اللَّهُ ‏ ‏الْإِنَابَةَ ‏","","",""],[14038,14038,"","আমরা তার কথা বলেছি, নাকি তার প্রতি ঈর্ষার কথা বলেছিলাম... ...আমার বাবার চিতা বলছে যে সে নাকি ঈশ্বর. সে কবরস্থানের জন্য একটা মই পেয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُلَيَّةَ ‏ ‏أَوْ غَيْرُهُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏تَجْصِيصِ ‏ ‏الْقُبُورِ ‏","","",""],[14039,14039,"","আমরা আমার বাবার সাথে যে টোপ নিয়ে কথা বলেছিলাম তা নিয়ে কথা বলেছিলাম। সেই গৌরবান্বিত ব্যক্তি বলবে যে সে জানতে চাইলে তাকে মেরে ফেলবে। আমি চাই তুমি এখানে চলে যাও। আপনার প্রভাব আপনার প্রভাব দ্বারা লেখা হয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏دَخَلَتْ ‏ ‏الْبِقَاعُ ‏ ‏حَوْلَ الْمَسْجِدِ فَأَرَادَ ‏ ‏بَنُو سَلِمَةَ ‏ ‏أَنْ يَنْتَقِلُوا قُرْبَ الْمَسْجِدِ فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُمْ إِنَّهُ بَلَغَنِي ‏ ‏أَنَّكُمْ تُرِيدُونَ أَنْ تَنْتَقِلُوا قُرْبَ الْمَسْجِدِ قَالُوا نَعَمْ يَا رَسُولَ اللَّهِ قَدْ أَرَدْنَا ذَلِكَ قَالَ فَقَالَ يَا ‏ ‏بَنِي سَلِمَةَ ‏ ‏دِيَارَكُمْ تُكْتَبْ آثَارُكُمْ دِيَارَكُمْ تُكْتَبْ آثَارُكُمْ ‏","","",""],[14040,14040,"","ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তিনি শেষ সময়ে তার টাকাপয়সা দাবি করে যে - বিষয়গুলো প্রতিজ্ঞা করেছেন, সেগুলো নিয়ে আমরা বাবার সঙ্গে কথা বলেছিলাম । ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏وَجَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَكُونُ فِي آخِرِ الزَّمَانِ خَلِيفَةٌ يَقْسِمُ الْمَالَ وَلَا يَعُدُّهُ ‏","","",""],[14041,14041,"","আমরা হয়তো সে বলেছে আমরা রাতে ছেলেটার সাথে রাত কাটাতে যাচ্ছি, সে এটা পেয়ে যাবে, আর সে ছেড়ে দেবে, তাই আমরা বড় হয়েছি, তারপর আমরা এগিয়ে যাবো।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏أَشْعَثُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا نُسَافِرُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا صَعِدْنَا كَبَّرْنَا وَإِذَا هَبَطْنَا سَبَّحْنَا ‏","","",""],[14042,14042,"","আমরা একজন কুকুর ছেলের কথা বলেছিলাম যে অতিথি বাবার ছেলে যাবে যাবে যাবে যাবে যাবেরের বলবে যে জাথারেরের প্রার্থনা করবে আর সিগাররা যে আমি ভালোবাসা দিচ্ছি তা আমি আর এটা সবচেয়ে ভালো মিথ্যাবাদী।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الدَّجَّالُ ‏ ‏أَعْوَرُ وَهُوَ أَشَدُّ الْكَذَّابِينَ ‏","","",""],[14043,14043,"","আমরা একটা কুকুর ছেলের কথা বলেছিলাম যে ছেলেটির কথা শুনে শুনে আমি বলব যখন আমরা মাতাল হয়ে যাব আর আমি তার প্রভুর হাত ভেঙ্গে ফেলব. আর ভাড়ার জন্য.","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرًا ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّمَا أَنَا بَشَرٌ وَإِنِّي أَشْتَرِطُ عَلَى رَبِّي أَيَّ عَبْدٍ مِنْ الْمُسْلِمِينَ شَتَمْتُهُ أَوْ سَبَبْتُهُ أَنْ يَكُونَ ذَلِكَ لَهُ زَكَاةً وَأَجْرًا ‏","","",""],[14044,14044,"","আমরা একটা কাপুরুষ ছেলের কথা বলেছিলাম যে আমাকে তার চেয়ে ভালো অনুভব করতে চেয়েছে, ঈশ্বর মঙ্গলভাবের যুক্তি নিয়ে কথা বলেন, আল্লাহ তা উদ্ধার করতে হবে আর তারপর সে তার পর সে তার বঁড়শি থেকে পড়ে গেছে। দেয়ালটা তো অন্য এপার্টমেন্টে যেতেই পারে।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏جَعْفَرُ بْنُ مُحَمَّدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ حَجَّةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ثُمَّ ‏ ‏نَزَلَ عَنْ ‏ ‏الصَّفَا ‏ ‏حَتَّى ‏ ‏انْصَبَّتْ ‏ ‏قَدَمَاهُ فِي ‏ ‏بَطْنِ الْوَادِي ‏ ‏سَعَى حَتَّى إِذَا صَعِدْنَا الشِّقَّ الْآخَرَ مَشَى ‏","","",""],[14045,14045,"","আমরা একটি বাচ্চা থাকার কথা বলেছিলাম যে আমার বাবা যাবে যাবে যাবে যাবে যাবে জাবেরেরেরের উত্তর। তিনি আমাকে বলেছেন, তিনি তার কাছে প্রার্থনা করতে চান। আগুনের শেষ টুকরো, আর আমি আশা করছি যে এই আগুন একটি জাতি আর বিশ্বের ক্ষতিকর প্রকৃতির দেবতাদের কষ্ট নিয়ে।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يُسْأَلُ عَنْ ‏ ‏الْمُهَلِّ ‏ ‏فَقَالَ سَمِعْتُ ثُمَّ انْتَهَى أُرَاهُ يُرِيدُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مُهَلُّ ‏ ‏أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏مِنْ ‏ ‏ذِي الْحُلَيْفَةِ ‏ ‏وَالطَّرِيقِ الْأُخْرَى ‏ ‏الْجُحْفَةِ ‏ ‏وَمُهَلُّ ‏ ‏أَهْلِ ‏ ‏الْعِرَاقِ ‏ ‏مِنْ ‏ ‏ذَاتِ عِرْقٍ ‏ ‏وَمُهَلُّ ‏ ‏أَهْلِ ‏ ‏نَجْدٍ ‏ ‏مِنْ ‏ ‏قَرْنٍ ‏ ‏وَمُهَلُّ أَهْلِ ‏ ‏الْيَمَنِ ‏ ‏مِنْ ‏ ‏يَلَمْلَمَ ‏","","",""],[14046,14046,"","আমরা একটা কুকুর ছেলে সম্পর্কে কথা বলেছিলাম যে ছেলেটি আমাকে শুনতে পাবে যে আমি তোমাকে একটা অন্ধ মেয়েকে ফোন করব... ... যাকে আমি আমার ভাইয়ের সাথে বসতে হবে. তাদের উপরে গিয়ে বল, সে কেন তাদের খুন করতে বলেছিল.","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرًا ‏ ‏يَقُولُ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِأَسْمَاءَ بِنْتِ عُمَيْسٍ ‏ ‏مَا شَأْنُ أَجْسَامِ بَنِي أَخِي ‏ ‏ضَارِعَةً ‏ ‏أَتُصِيبُهُمْ حَاجَةٌ قَالَتْ لَا وَلَكِنْ تُسْرِعُ إِلَيْهِمْ الْعَيْنُ ‏ ‏أَفَنَرْقِيهِمْ قَالَ وَبِمَاذَا فَعَرَضَتْ عَلَيْهِ فَقَالَ ارْقِيهِمْ ‏","","",""],[14047,14047,"","আমি বলব সে ঈশ্বরকে জানে আর বলে সে ঈশ্বর হবে ঈশ্বর আর সে বলবে যে সে ঈশ্বর হবে. আর ওই মহিলা তাকেও.","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَعَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنْ كَانَ شَيْءٌ فَفِي ‏ ‏الرَّبْعِ ‏ ‏وَالْفَرَسِ وَالْمَرْأَةِ ‏","","",""],[14048,14048,"","আমরা একটি পিপাপি পুত্র নিয়ে কথা বলেছি যে গ্রাহকের বাবা যাবে যাবে যাবে যাবে জেরেরের উত্তর। তাকে খুন করার ব্যাপারে হাল ছেড়ে দিয়ে বলো যে তুমি ঐ বালের দেবতা যার টাকা আছে।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏أَمَرَنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَتْلِ الْكِلَابِ حَتَّى إِنَّ الْمَرْأَةَ تَقْدَمُ مِنْ الْبَادِيَةِ بِكَلْبِهَا فَنَقْتُلُهُ ثُمَّ ‏ ‏نَهَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ قَتْلِهَا وَقَالَ عَلَيْكُمْ بِالْأَسْوَدِ ‏ ‏الْبَهِيمِ ‏ ‏ذِي النُّقْطَتَيْنِ فَإِنَّهُ شَيْطَانٌ ‏","","",""],[14049,14049,"","আমরা একটি বাচ্চা ছেলের কথা বলেছিলাম যে আমাকে সাহায্য করতে বলেছে। সে বলল, কেন সে একটি গ্রীষ্মের মধ্যে বসবাসের সময় প্রবেশ করেছে ঈশ্বরের দোহাই দিয়ে এবং সে তার আত্মা সমর্পণ করেছে। এটা একটা ভাল ছেলের জন্য। এটা একটা ভাল কথা, আমি জানি, আমি এটা করতে পারি না। আমি এটা করতে চাই। আমি জানি, আমি এটা করতে চাই না। আমি এটা করতে চাই না। আমি এটা করতে চাই। আমি জানি, আমি এটা করতে চাই না। আমি এটা আমার জন্য অনেক ভালো। আমি এটা করতে পারি। আমি যা করি, আমি এটা আমার মন, আমি শুধু চাই। আমি জানি, আমি এটা করি, আমি এটা আমার জন্য যে আমি এটা করি। আমি এটা আমার জন্য যে, আমি শুধু একটা ভাল কাজ করি। আমি যদি আমি এটা করি, আমি এটা করি, আমি এটা করি, আমি জানি যে, আমি এটা আমার বাবা-মা, আমি জানি যে এটা করি। আমি এটা আমার বাবা-মা'র মন, আমি জানি যে, আমি এটা একটা ভালো কাজ করি। প্রভুর শপথে বলা হয়েছে, তারা তোমার মায়ের জন্য খুন করবে, কিন্তু একমাত্র পিপাসার্ত।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏زِيَادُ بْنُ إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ عَتِيقٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا دَخَلَتْ ‏ ‏صَفِيَّةُ بِنْتُ حُيَيٍّ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فُسْطَاطَهُ ‏ ‏حَضَرَ نَاسٌ وَحَضَرْتُ مَعَهُمْ لِيَكُونَ فِيهَا قَسْمٌ فَخَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏قُومُوا عَنْ أُمِّكُمْ فَلَمَّا كَانَ مِنْ الْعَشِيِّ حَضَرْنَا فَخَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيْنَا فِي طَرَفِ رِدَائِهِ نَحْوٌ مِنْ ‏ ‏مُدٍّ ‏ ‏وَنِصْفٍ مِنْ تَمْرٍ عَجْوَةٍ فَقَالَ كُلُوا مِنْ وَلِيمَةِ أُمِّكُمْ ‏","","",""],[14050,14050,"","আমরা একটা কুকুর ছেলে নিয়ে কথা বলেছি, বাবা আমাদের এটা করতে বলেছেন আর উনি বলবেন যে বিশ্বাস একটা করে খেয়ে ফেলবে আর অনেক মানুষ পৃথিবীতে খায়।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ إِنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الْمُؤْمِنَ يَأْكُلُ فِي مِعًى وَاحِدٍ وَالْكَافِرُ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ ‏","","",""],[14051,14051,"","আমরা একজন লোক সম্পর্কে কথা বলেছিলাম যে একটা ম্যাচ শুনতে পায়, লর্ড তার জন্য প্রার্থনা করে আর সে যুদ্ধে তাদের সাথে তার মন খেলবার জন্য চলে যেত। আপনার পরিদর্শনের পর, সে আপনার কাছে করেছে, তারপর আমি আপনাকে সেই দিনের নগ্ন অবস্থায় দেখেছি।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَنْقُلُ مَعَهُمْ الْحِجَارَةَ ‏ ‏لِلْكَعْبَةِ ‏ ‏وَعَلَيْهِ ‏ ‏إِزَارٌ ‏ ‏فَقَالَ لَهُ ‏ ‏الْعَبَّاسُ ‏ ‏عَمُّهُ يَا ابْنَ أَخِي لَوْ حَلَلْتَ ‏ ‏إِزَارَكَ ‏ ‏فَجَعَلْتَهُ عَلَى ‏ ‏مَنْكِبَيْكَ ‏ ‏دُونَ الْحِجَارَةِ قَالَ فَحَلَّهُ فَجَعَلَهُ عَلَى ‏ ‏مَنْكِبَيْهِ ‏ ‏فَسَقَطَ مَغْشِيًّا عَلَيْهِ فَمَا رُئِيَ بَعْدَ ذَلِكَ الْيَوْمِ عُرْيَانًا ‏","","",""],[14052,14052,"","ঈশ্বর তাকে দাবি করেছেন এবং দুর্দশা ও দুর্দশার মধ্যে তার যাত্রা ব্যর্থ হওয়ার জন্য প্রাচীরের ওপর আশ্বস্ত করতে ব্যর্থ হওয়ার বিষয়ে প্রতিজ্ঞা করেছেন । এই দু'জন পুত্র, তাকে জিজ্ঞাসা করে যে, লোকেরা তাকে ধোঁকা দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏طَافَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ عَلَى رَاحِلَتِهِ ‏ ‏بِالْبَيْتِ ‏ ‏وَبَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏لِيَرَاهُ النَّاسُ وَلِيُشْرِفَ وَيَسْأَلُوهُ إِنَّ النَّاسَ غَشُوهُ ‏","","",""],[14053,14053,"","আমরা একটি বাচ্চা থাকার কথা বলেছিলাম যে কাস্টমারের বাবা যাবে যাবে যাবে যাবে যাবে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَمُوتَنَّ أَحَدُكُمْ إِلَّا وَهُوَ يُحْسِنُ الظَّنَّ بِاللَّهِ ‏","","",""],[14054,14054,"","আমরা যে বধিরদের কথা বলেছিলাম, তাদের কথা বলেছিলাম আমরা ওর জন্য প্রার্থনা করবো আর সে তার ক্ষতি ভুলে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏صَنَعْنَا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَّارَةً فَأَتَيْتُهُ بِهَا فَوَضَعْتُهَا بَيْنَ يَدَيْهِ فَاطَّلَعَ فِيهَا فَقَالَ ‏ ‏حَسِبْتُهُ لَحْمًا فَذَكَرْتُ ذَلِكَ ‏ ‏لِأَهْلِي ‏ ‏فَذَبَحُوا لَهُ شَاةً ‏","","",""],[14055,14055,"","ঈশ্বর এমন উত্তম যুক্তি প্রদান করেছেন, যা স্বর্গে, প্রভু, এবং উড়িয়ে দেওয়ার মতো লজ্জা নিয়ে আসে না । সিঁড়ি দিয়ে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ ثَابِتٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَجٌّ مَبْرُورٌ لَيْسَ لَهُ جَزَاءٌ إِلَّا الْجَنَّةَ قَالُوا يَا نَبِيَّ اللَّهِ مَا الْحَجُّ الْمَبْرُورُ قَالَ إِطْعَامُ الطَّعَامِ وَإِفْشَاءُ السَّلَامِ ‏","","",""],[14056,14056,"","আমরা আমার প্রিয় বাবা যা বলেছিলেন, তা নিয়ে কথা বলার চেষ্টা করেছিলাম । যে লোক এই জন ্ য বেঁচে থাকবে সে-ই তবে যে ব ্ যক ্ তি হবে নিরাপদ , সে-ই হবে ক ্ ষমতার অধিকারী । সেই ব্যক্তি হবেন সেই ব্যক্তি, যিনি রাজা হবেন ।","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنُ بْنُ الْمُثَنَّى أَبُو عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏لَمْ يَكُنْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْزُو فِي الشَّهْرِ الْحَرَامِ إِلَّا أَنْ ‏ ‏يُغْزَى أَوْ يُغْزَوْا فَإِذَا حَضَرَ ذَلِكَ أَقَامَ حَتَّى ‏ ‏يَنْسَلِخَ ‏","","",""],[14057,14057,"","আমরা দুটো ঘোড়ার কথা বলেছি আর আমরা আমার বাবার বিদায়ের কথা বলেছি যা আগে কখনো হয়নি, আমি ঈশ্বরের দোহাইর কাছে গুলি করবো আর আমি তোমাকে দিয়ে দেবো।","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ أَفِي الْعَقْرَبِ رُقْيَةٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اسْتَطَاعَ مِنْكُمْ أَنْ يَنْفَعَ أَخَاهُ فَلْيَفْعَلْ ‏","","",""],[14058,14058,"","আমরা দুটো তর্কের কথা বলেছি আর আমাদের উপর বিরক্ত হয়ে... ...আমার প্রিয় কাস্টমারের কাছে... ...ঈশ্বরের উত্তর জানার জন্য... তিনি একবার তিন বার যেতে রাজি হয়েছিলেন এবং শেষ বারের মতো তিনি নিজেকে পছন্দ করতেন এবং বলেন \"শেষ পর্যন্ত একজন\"","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اعْتَزَلَ نِسَاءَهُ شَهْرًا فَخَرَجَ إِلَيْنَا فِي تِسْعٍ وَعِشْرِينَ فَقُلْنَا إِنَّمَا الْيَوْمُ تِسْعٌ وَعِشْرُونَ فَقَالَ ‏ ‏إِنَّمَا الشَّهْرُ وَصَفَّقَ بِيَدَيْهِ ثَلَاثَ مَرَّاتٍ وَحَبَسَ إِصْبَعًا وَاحِدًا فِي الْآخِرَةِ ‏ ‏وَقَالَ ‏ ‏يُونُسُ ‏ ‏أُصْبُعًا وَاحِدَةً ‏","","",""],[14059,14059,"","আমরা একটা ঘোড়ার কথা বলেছিলাম, কিন্তু একদিন আমাদের কাছে এমন একটা ঘোড়ার কথা বলেছিলাম, যে আপনার বাবার সাহায্যে ফিরে আসবে বলে ঈশ্বর তাঁর কাছে প্রতিজ্ঞা করেছিলেন এবং তার কাজ করেছেন আমি তাকে বলেছি যে, আমি তাকে কিছু কল করার আগ পর্যন্ত সে মদ খেয়ে আছে। তার কৌতুক।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ الْحُصَيْنِ ‏ ‏عَنْ ‏ ‏وَاقِدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ سَعْدِ بْنِ مُعَاذٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا خَطَبَ أَحَدُكُمْ الْمَرْأَةَ فَإِنْ اسْتَطَاعَ أَنْ يَنْظُرَ مِنْهَا إِلَى مَا يَدْعُوهُ إِلَى نِكَاحِهَا فَلْيَفْعَلْ ‏ ‏قَالَ ‏ ‏فَخَطَبْتُ ‏ ‏جَارِيَةً ‏ ‏مِنْ ‏ ‏بَنِي سَلِمَةَ ‏ ‏فَكُنْتُ أَخْتَبِئُ لَهَا تَحْتَ ‏ ‏الْكَرَبِ ‏ ‏حَتَّى رَأَيْتُ مِنْهَا بَعْضَ مَا دَعَانِي إِلَى نِكَاحِهَا فَتَزَوَّجْتُهَا ‏","","",""],[14060,14060,"","আমরা আমার ছেলে পৃথিবীর দিকে ঘুরেছি, ঈশ্বর এই টাকা হাতিয়ে দিয়েছেন আর যদি শয়তান টাকা খায় তাহলে তুমি টাকা খাবে না।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏وَحُجَيْنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَأْكُلُوا بِالشِّمَالِ فَإِنَّ الشَّيْطَانَ يَأْكُلُ بِالشِّمَالِ ‏","","",""],[14061,14061,"","আমি প্রার্থনা করছি, মাতাল হবার আগে সে ভালো মুখটা পেয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏وَحُجَيْنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَنِي لِحَاجَةٍ ثُمَّ أَدْرَكْتُهُ فَسَلَّمْتُ عَلَيْهِ فَأَشَارَ إِلَيَّ فَلَمَّا فَرَغَ دَعَانِي فَقَالَ ‏ ‏إِنَّكَ سَلَّمْتَ عَلَيَّ ‏ ‏آنِفًا ‏ ‏وَأَنَا أُصَلِّي وَهُوَ مُوَجِّهٌ حِينَئِذٍ قِبَلَ الْمَشْرِقِ ‏","","",""],[14062,14062,"","আমরা আমার সহকর্মীর কথা বলেছিলাম, আমি ভবিষ্যতের ভবিষ্যদ্বাণীর ব্যাপারে ফাঁস হয়ে গেছি। একজন দেবতা হিসেবে আমি তার সাহসকে নরকে যেতে দেখেছি। আমি তাকে দেখতে পাচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَحُجَيْنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏عُرِضَ عَلَيَّ الْأَنْبِيَاءُ فَإِذَا ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏رَجُلٌ ضَرْبٌ مِنْ الرِّجَالِ كَأَنَّهُ مِنْ رِجَالِ ‏ ‏شَنُوءَةَ ‏ ‏فَرَأَيْتُ ‏ ‏عِيسَى ابْنَ مَرْيَمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَإِذَا أَقْرَبُ مَنْ رَأَيْتُ بِهِ شَبَهًا ‏ ‏عُرْوَةُ بْنُ مَسْعُودٍ ‏ ‏وَرَأَيْتُ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَإِذَا أَقْرَبُ مَنْ رَأَيْتُ بِهِ شَبَهًا صَاحِبُكُمْ ‏ ‏يَعْنِي نَفْسَهُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَأَيْتُ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَإِذَا أَقْرَبُ مَنْ رَأَيْتُ بِهِ شَبَهًا ‏ ‏دِحْيَةُ ‏","","",""],[14063,14063,"","আমি আমার বাবার সাথে কথা বলেছি যে তোমার সন্দেহের কথা তাকে ঈশ্বরের কাছে জিজ্ঞেস করা উচিত, সে আমাদের একটা বিরতি দেবে আর তাকে দেখতে পাবে আর সে ভালো ছেলে, আমি যখন ফিরে যাব তখন আমরা ফিরে আসবো উড়িয়ে দিবে, তাদের রাজারা আসছে, তারা তোমার সেরাটা করবে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَحُجَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏اشْتَكَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّيْنَا وَرَاءَهُ وَهُوَ قَاعِدٌ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يُكَبِّرُ يُسْمِعُ النَّاسَ تَكْبِيرَهُ فَالْتَفَتَ إِلَيْنَا فَرَآنَا قِيَامًا فَأَشَارَ إِلَيْنَا فَقَعَدْنَا فَصَلَّيْنَا بِصَلَاتِهِ قُعُودًا فَلَمَّا صَلَّى قَالَ إِنْ كِدْتُمْ ‏ ‏آنِفًا ‏ ‏تَفْعَلُونَ فِعْلَ ‏ ‏فَارِسَ ‏ ‏وَالرُّومِ ‏ ‏يَقُومُونَ عَلَى مُلُوكِهِمْ وَهُمْ قُعُودٌ فَلَا تَفْعَلُوا ‏ ‏ائْتَمُّوا بِأَئِمَّتِكُمْ إِنْ صَلَّى قَائِمًا فَصَلُّوا قِيَامًا وَإِنْ صَلَّى قَاعِدًا فَصَلُّوا قُعُودًا ‏","","",""],[14064,14064,"","আমরা আমার বাবার সাথে আমার বাবার মত কথা বলেছিলাম যে আমার বাবার সাথে ও ঈশ্বরের মত উড়তে চেয়েছিল, ঈশ্বর বলেছিলেন যখন আমরা প্রভুর অনুগ্রহে ছিলাম, তিনি যদি কখনও তার ইচ্ছার কথা প্রকাশ করতেন। ঈশ্বর বলেন, ঈশ্বর ঈশ্বর যখন একজন দেবতাহীন অন্ত্যেষ্টিক্রিয়ার সময় তাকে ঈশ্বর বলেছিলেন, তিনি একজন দেবতা দেবতা হবেন ।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ يَعْنِي الْعَطَّارَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ مِقْسَمٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ مَرَّتْ جَنَازَةٌ فَذَهَبْنَا لِنَحْمِلَ فَإِذَا جَنَازَةُ يَهُودِيٍّ ‏ ‏أَوْ يَهُودِيَّةٍ ‏ ‏فَقُلْنَا يَا رَسُولَ اللَّهِ إِنَّمَا كَانَتْ جَنَازَةَ يَهُودِيٍّ ‏ ‏أَوْ يَهُودِيَّةٍ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَوْتُ فَزَعٌ فَإِذَا رَأَيْتُمْ جَنَازَةً فَقُومُوا ‏","","",""],[14065,14065,"","আমরা একটা নির্দিষ্ট ছেলের কথা বলেছি আর আমরা একটি হুট করে খাওয়ার চেষ্টা করার পর তিনি শ্বশুরের শ্বশুরের শ্বশুরের সাথে কথা বলেছি। যাবের বলেছিলেন, \"তার কাছে প্রার্থনা করুন।\" প্রভু আল্লাহ্‌ আল-জাগর। পরবর্তী প্রজন্মের মধ্যে পঞ্চম প্রজন্ম ছিল মানুষ হলো শত্রু।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ مُحَمَّدٍ وَهُوَ أَبُو إِبْرَاهِيمَ الْمُعَقِّبُ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏السَّائِبَةُ ‏ ‏و قَالَ ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏السَّائِمَةُ ‏ ‏جُبَارٌ ‏ ‏وَالْجُبُّ ‏ ‏جُبَارٌ ‏ ‏وَالْمَعْدِنُ ‏ ‏جُبَارٌ ‏ ‏وَفِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمُسُ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏الشَّعْبِيُّ ‏ ‏الرِّكَازُ ‏ ‏الْكَنْزُ الْعَادِي ‏","","",""],[14066,14066,"","আমরা আগেও যা ঘটেছে তার কথা বলেছি। ঈশ্বর হয়তো তার জন্য প্রার্থনা করেছেন এবং তিনি গত ছয় বছরের জন্য তাকে বিগত বছর নির্ধারণ করবেন।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏مُجَالِدُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنِي ‏ ‏الشَّعْبِيُّ ‏ ‏حَدَّثَنِي ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَنَّ ‏ ‏الْجَزُورَ ‏ ‏وَالْبَقَرَةَ عَنْ سَبْعَةٍ ‏","","",""],[14067,14067,"","আমি যে - বিষয়গুলো করতে চেয়েছিলাম, সেগুলো নিয়ে আমি কতটা ভালভাবে কথা বলেছিলাম এবং ভিতরে ঢুকতে চেয়েছিলাম, সেই সম্বন্ধে আমরা কথা বলেছিলাম । আমি তোমার মত আমার কারাগারে যেতে চাই । তোমার ভাইয়ের সাথে কখনো পশমের ব্যবহার হয়েছে... ...আর তারপর সে তার হৃদয় হারিয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ يَعْنِي ابْنَ الْغَسِيلِ ‏ ‏حَدَّثَنِي ‏ ‏شُرَحْبِيلُ أَبُو سَعْدٍ ‏ ‏أَنَّهُ ‏ ‏دَخَلَ عَلَى ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي فِي ثَوْبٍ وَاحِدٍ وَحَوْلَهُ ثِيَابٌ فَلَمَّا فَرَغَ مِنْ صَلَاتِهِ قَالَ قُلْتُ غَفَرَ اللَّهُ لَكَ يَا ‏ ‏أَبَا عَبْدِ اللَّهِ ‏ ‏تُصَلِّي فِي ثَوْبٍ وَاحِدٍ وَهَذِهِ ثِيَابُكَ إِلَى جَنْبِكَ قَالَ أَرَدْتُ أَنْ يَدْخُلَ عَلَيَّ الْأَحْمَقُ مِثْلُكَ ‏ ‏فَيَرَانِي أُصَلِّي فِي ثَوْبٍ وَاحِدٍ أَوَكَانَ لِكُلِّ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَوْبَانِ قَالَ ثُمَّ أَنْشَأَ ‏ ‏جَابِرٌ ‏ ‏يُحَدِّثُنَا فَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا مَا اتَّسَعَ الثَّوْبُ فَتَعَاطَفْ بِهِ عَلَى مَنْكِبَيْكَ ثُمَّ صَلِّ وَإِذَا ضَاقَ عَنْ ذَاكَ فَشُدَّ بِهِ ‏ ‏حَقْوَيْكَ ‏ ‏ثُمَّ صَلِّ مِنْ غَيْرِ رِدَاءٍ لَهُ ‏","","",""],[14068,14068,"","আমরা ঈশ্বরের কথা বলেছিলাম যে আমার কথা শুনতে ভালো লাগছে, নবী তার কাছে প্রার্থনা করছে আর বলবে সে ভয় পাবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ الْمَخْزُومِيُّ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏غِلَظُ الْقُلُوبِ وَالْجَفَاءُ فِي أَهْلِ الْمَشْرِقِ وَالْإِيمَانُ فِي أَهْلِ ‏ ‏الْحِجَازِ ‏","","",""],[14069,14069,"","আমি এমন এক বাচ্চার কথা বলেছিলাম, যিনি আমাকে আমার শোনা সবচেয়ে ভাল মানুষ হতে বলেছিলেন । যে লোক এই জন ্ য বেঁচে থাকবে সে-ই তবে যে ব ্ যক ্ তি হবে নিরাপদ , সে-ই হবে ক ্ ষমতার অধিকারী । সেই ব্যক্তি হবেন সেই ব্যক্তি, যিনি হবেন সেই ব্যক্তি, যিনি রাজা হবেন। আমি অন্যায়ের মধ্য দিয়ে যাচ্ছি, ঈশ্বরের ইচ্ছা আছে। সে যা করতে পারে, সে এই বাড়িতে প্রবেশ করে যতক্ষণ না সে কথা বলছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَزْعُمُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ الصُّوَرِ فِي الْبَيْتِ وَنَهَى الرَّجُلَ أَنْ يَصْنَعَ ذَلِكَ وَأَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏زَمَنَ الْفَتْحِ وَهُوَ ‏ ‏بِالْبَطْحَاءِ ‏ ‏أَنْ يَأْتِيَ ‏ ‏الْكَعْبَةَ ‏ ‏فَيَمْحُوَ كُلَّ صُورَةٍ فِيهَا وَلَمْ يَدْخُلْ ‏ ‏الْبَيْتَ ‏ ‏حَتَّى مُحِيَتْ كُلُّ صُورَةٍ فِيهِ ‏","","",""],[14070,14070,"","আমরা চেষ্টা করেছি আমরা কার সময় নষ্ট করেছি, ভবিষ্যদ্বাণীর উত্তর পাওয়ার জন্য, ঈশ্বর প্রার্থনা করেছেন যে তিনি সব ভাল কাজের জন্য বলেছেন.","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَبْدِ رَبِّهِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لِكُلِّ دَاءٍ دَوَاءٌ فَإِذَا أَصَبْتَ دَوَاءَ الدَّاءِ بَرَأَ بِإِذْنِ اللَّهِ تَعَالَى ‏","","",""],[14071,14071,"","তিনি ঈশ্বরের কাছে ফিরে এসে এই দৃঢ়প্রত্যয়ী হয়েছিলেন যে, তিনি তাকে সাহায্য করবেন, যতক্ষণ না তিনি আক্রমণ করা হয় । যে আরোগ্যশীল পৃথিবীতে বলে","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرٌو ‏ ‏أَنَّ ‏ ‏بُكَيْرًا ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏عَاصِمَ بْنَ عُمَرَ بْنِ قَتَادَةَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏عَادَ ‏ ‏الْمُقَنَّعَ ‏ ‏فَقَالَ لَا أَبْرَحُ حَتَّى ‏ ‏تَحْتَجِمَ ‏ ‏فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ فِيهِ الشِّفَاءَ ‏","","",""],[14072,14072,"","আমরা সবাই কথা বলেছি, ঈশ্বর আমাদের সহ্য করতে এনেছেন, ঈশ্বরের অনুগ্রহ আছে, ঈশ্বরের দয়ায় আছে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ مُحَمَّدُ بْنُ مُسْلِمٍ ‏ ‏مَوْلَى ‏ ‏حَكِيمِ بْنِ حِزَامٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ صَاحِبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏النُّهْبَةِ ‏","","",""],[14073,14073,"","আমরা আমার বাবার কথা বলেছিলাম, যে বাবা আমাকে বলেছে, ঈশ্বর এমন কিছু করতে বলছেন যেটা হয়তো ওর মুখে ফাঁস হয়ে গেছে বা তার মুখের গোপন কথা বলে। ঈশ্বর জানতেন এবং যে সকল ভালো কাজ করে তার হাতে ছেড়ে দেওয়া হয়।","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرٌو ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ أَنَعْمَلُ لِأَمْرٍ قَدْ فُرِغَ مِنْهُ أَمْ لِأَمْرٍ ‏ ‏نَأْتَنِفُهُ ‏ ‏قَالَ لِأَمْرٍ قَدْ فُرِغَ مِنْهُ فَقَالَ ‏ ‏سُرَاقَةُ ‏ ‏فَفِيمَ الْعَمَلُ إِذًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ عَامِلٍ مُيَسَّرٌ لِعَمَلِهِ ‏","","",""],[14074,14074,"","আমরা ভালো করেই বলেছি যে আমরা ফাদার আল-জাবিকে কিছু করার কথা বলেছি, ঈশ্বরের দোহাইর জন্য উত্তর দেবার জন্য। তিনি আত্মসমর্পণ করেছেন এবং বলেছেন যে, এক ঘন্টা ধরে তিনি এই বিষয়ে কথা বলেছেন যে, আমি এক ঘণ্টা ধরে থেমেছি। আমি এই বিষয়ে কথা বলেছি, আমি আমার ছেলে, আমি এই বিষয়ে কথা বলেছি, আমি এই বিষয়ে কথা বলেছি, আমি একজন ছেলে, আমি জানি যে কিনা আমার বাবা আল-জাবি, আমি এই বিষয়ে কথা বলেছি। আমি মনে করি, আমি এই বিষয়ে আমার বাবা-জাগের সাথে কথা বলেছি। আমি যখন জিজ্ঞেস করলাম, আমি মনে করি, আমি মনে করি, আমি জানি না যে, আমি এই বিষয়ে কিছু করতে চাই না যে, আমি জানি না যে, আমি তাকে আমি জানি না যে, আমি জানি না যে, আমি জানি, আমি কি করব। আমি জানি না। আমি জানি না যে, আমি তাকে আমি জানি না যে, আমি এই বিষয়ে কিছু করতে হবে। আমি তাকে আমি বলছি, আমি বলছি, আমি জানি না। আমি কি করব। আমি জানি না। ভালোবাসার কাপড়।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ وَجَدَ سَعَةً فَلْيُكَفِّنْ فِي ثَوْبِ ‏ ‏حِبَرَةٍ ‏","","",""],[14075,14075,"","আমরা সবাই একটা ছেলে কথা শুনেছি, আমরা কথা শুনেছি, সে একটা মরুভূমিতে একজন মহিলাকে নির্যাতন করতো, না হয় একটা বিড়ালের শিখার আগ পর্যন্ত আর তাকে পাঠানো হয়।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏عُذِّبَتْ امْرَأَةٌ فِي ‏ ‏هِرٍّ ‏ ‏أَوْ ‏ ‏هِرَّةٍ ‏ ‏رَبَطَتْهُ حَتَّى مَاتَ وَلَمْ تُرْسِلْهُ فَيَأْكُلَ مِنْ ‏ ‏خَشَاشِ ‏ ‏الْأَرْضِ فَوَجَبَتْ لَهَا النَّارُ بِذَلِكَ ‏","","",""],[14076,14076,"","আমরা কথা বলেছি ভালো মানুষ সম্পর্কে আমাদের বাবার সাথে কথা বলেছি। আমি একজন যুবককে জিজ্ঞাসা করছি, তিনি পঞ্চম পর্যায়ের ভগবানকে দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏أَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمُسُ ‏ ‏فَقَالَ نَعَمْ ‏","","",""],[14077,14077,"","আমরা একটা ছেলের কথা বলেছিলাম, আমরা একজন ভালো বাবা হওয়ার ব্যাপারে কথা বলেছি, আমি তার সাথে কথা বলব, যাকে আমি ভালোবাসি এবং ঈশ্বরের কাছে চিঠি লিখি এবং মৃত্যুর আগে তাকে আত্মসমর্পণ করি।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْعَبْدُ مَعَ مَنْ أَحَبَّ وَكَتَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبْلَ أَنْ يَمُوتَ إِلَى ‏ ‏كِسْرَى ‏ ‏وَقَيْصَرَ ‏ ‏وَإِلَى كُلِّ جَبَّارٍ ‏","","",""],[14078,14078,"","আমরা একটা ছেলের কথা বলেছি যে আমাদের সাথে ঈশ্বরের কথা বলেছে, সে মারা গেছে, আর তারা মাতাল।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَدِّدُوا ‏ ‏وَأَبْشِرُوا ‏","","",""],[14079,14079,"","আমরা একটা ছেলের কথা বলেছিলাম, আমরা একজন ভালো বাবা হওয়ার কথা বলেছিলাম, আমি বলব আমি ঈশ্বরের কাছে জীবন উৎসর্গ করেছি... ...আমি একটা আশীর্বাদ আর সৌভাগ্যের জন্য কল করছি. সে বলল তার একটা আশীর্বাদ আছে. সে চলে যাবে, সে তোমার জন্য লজ্জিত, সে আমাকে তার বিয়ে করার জন্য ভগবানকে ধার দিতে চায় আর তারপর তাকে ছেড়ে দেয়।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنْ عِشْتُ إِنْ شَاءَ اللَّهُ ‏ ‏زَجَرْتُ ‏ ‏أَنْ يُسَمَّى بَرَكَةُ وَيَسَارٌ وَنَافِعٍ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏لَا أَدْرِي ذَكَرَ رَافِعًا أَمْ لَا ‏ ‏إِنَّهُ يُقَالُ لَهُ هَاهُنَا بَرَكَةٌ فَيُقَالُ لَا وَيُقَالُ هَاهُنَا يَسَارٌ فَيُقَالُ لَا قَالَ فَقُبِضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَمْ ‏ ‏يَزْجُرْ ‏ ‏عَنْ ذَلِكَ ‏ ‏فَأَرَادَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنْ ‏ ‏يَزْجُرَ ‏ ‏عَنْهُ ثُمَّ تَرَكَهُ ‏","","",""],[14080,14080,"","আমি যে - উত্তম বাবা যাবে বলে উল্লেখ করেছিলাম, তার একটা ছেলে আমার প্রতি ঈর্ষা প্রকাশ করেছিল । তারা রাতের বেলা ঈশ্বরের কাছে প্রার্থনা করেছিল যেন তিনি সকালে তাকে আত্মসমর্পণ করার জন্য তার কাছে প্রার্থনা করেন ।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَخْبَرَنِي ‏ ‏جَابِرٌ ‏ ‏أَنَّ أَمِيرَ الْبَعْثِ كَانَ ‏ ‏غَالِبًا اللَّيْثِيَّ ‏ ‏وَقُطْبَةَ بْنَ عَامِرٍ ‏ ‏الَّذِي دَخَلَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّخْلَ وَهُوَ مُحْرِمٌ ثُمَّ خَرَجَ مِنْ الْبَابِ وَقَدْ تَسَوَّرَ مِنْ قِبَلِ الْجِدَارِ ‏ ‏وَعَبْدُ اللَّهِ بْنُ أُنَيْسٍ ‏ ‏الَّذِي سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ لَيْلَةِ الْقَدْرِ وَقَدْ خَلَتْ اثْنَانِ وَعِشْرُونَ لَيْلَةً فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْتَمِسْهَا فِي هَذِهِ السَّبْعِ الْأَوَاخِرِ الَّتِي بَقِينَ مِنْ الشَّهْرِ ‏","","",""],[14081,14081,"","আমরা কথা বলেছিলাম একটা ছেলের সাথে কথা বলতে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا تَغَوَّطَ أَحَدُكُمْ فَلْيَمْسَحْ ثَلَاثَ مَرَّاتٍ ‏","","",""],[14082,14082,"","আমরা সবাই কথা বলেছি, আমরা ইতিমধ্যে ভালো বাবা বলেছেন আমি জিনের কাছে যেতে পেরে খুশি হব, ঈশ্বর প্রার্থনা করেছেন সে উদ্ধার করতে হবে এবং সে চলে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ السُّجُودِ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُ أَنْ يُعْتَدَلَ فِي السُّجُودِ وَلَا يَسْجُدَ الرَّجُلُ وَهُوَ بَاسِطٌ ذِرَاعَيْهِ ‏","","",""],[14083,14083,"","আমরা একটি ছেলে কথা বলেছি যে প্রভুর বাবা-মার সাথে কথা বলেছে, সে বলেছিল, সে নাকি প্রার্থনা শুনবে পরে রাজ্যের নির্দেশনা থেকে রাজ্য ক্ষতি হবে.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الشَّيْطَانَ إِذَا سَمِعَ نِدَاءَ الصَّلَاةِ فَرَّ بُعْدَ مَا بَيْنَ ‏ ‏الرَّوْحَاءِ ‏ ‏وَالْمَدِينَةِ ‏ ‏لَهُ ضُرَاطٌ ‏","","",""],[14084,14084,"","আমরা কথা বলেছি একটি ছেলে কথা বলে এই ব্যাপারে কথা বলতে যে সে অনেক পরিকল্পনা করবে আমরা বলতে পারি যে আমরা কি করতে পারি স্কলার থেকে সরে যেতে পারি, আমরা ঈশ্বরের ইচ্ছার দিকে যাত্রা করেছি এবং সে হবে তোমার জন্য ছেড়ে দাও আর বলো যে তুমি ঐ ওকের উপর দিয়ে ঢুকতে পারবে না।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏أَسَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ فِي كَثْرَةِ ‏ ‏خُطَا الرَّجُلِ إِلَى الْمَسْجِدِ شَيْئًا فَقَالَ هَمَمْنَا أَنْ نَنْتَقِلَ مِنْ دُورِنَا إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏لِقُرْبِ الْمَسْجِدِ ‏ ‏فَزَجَرَنَا ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ وَقَالَ ‏ ‏لَا تُعْرُوا ‏ ‏الْمَدِينَةَ ‏ ‏فَإِنَّ لَكُمْ فَضِيلَةً عَلَى مَنْ عِنْدَ الْمَسْجِدِ بِكُلِّ خُطْوَةٍ دَرَجَةً ‏","","",""],[14085,14085,"","আমরা একটা ছেলের কথা বলেছিলাম, আমরা একটা ছেলের সাথে কথা বলেছিলাম, সে বাতাসে কি করতে যাচ্ছে সে সম্পর্কে ভাল কথা বলবে, তাদেরকে সিঁড়ি আর গৌরব দিয়ে পাবে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏خَيْرُ مَا رُكِبَتْ إِلَيْهِ ‏ ‏الرَّوَاحِلُ ‏ ‏مَسْجِدُ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَمَسْجِدِي ‏","","",""],[14086,14086,"","আমরা একটা ছেলের কথা বলেছি যে প্রভুর বাবা-মা'র সাথে কথা বলেছে, সে একটু বেশি বেঁচে যাবে অথবা উজ্জ্বল হয়ে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ ‏ ‏يُسْتَنْجَى ‏ ‏بِبَعْرَةٍ ‏ ‏أَوْ بِعَظْمٍ ‏","","",""],[14087,14087,"","আমরা সবাই একটা ছেলের কথা বলেছি যে আমাদের সাথে কথা বলেছে, তাকে পাপ ছেড়ে দিতে হবে আর ঈশ্বরের অনুগ্রহ আছে প্রভুর প্রেমের জন্য। তার সব দর্শন না পাওয়া পর্যন্ত তাকে দেখা হয়।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏حَدَّثَنِي ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏زَمَانَ الْفَتْحِ أَنْ يَأْتِيَ ‏ ‏الْبَيْتَ ‏ ‏وَهُوَ ‏ ‏بِالْبَطْحَاءِ ‏ ‏فَيَمْحُوَ كُلَّ صُورَةٍ فِيهِ وَلَمْ يَدْخُلْهُ حَتَّى مُحِيَتْ كُلُّ صُورَةٍ فِيهِ ‏","","",""],[14088,14088,"","আমরা সবাই একটা ছেলের কথা বলেছি... ...যে গুডস এর বাবা বলেছেন আমি বিষের ব্যাপারে একটা প্রশ্ন করব, ঈশ্বর বলতে চাচ্ছে যে সে বলছে না যে শহর শেষ পর্যন্ত আর আমি নই শেষ কাজটি করাটা আমার পক্ষে দোষ দেয়া সম্ভব না।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ ‏ ‏الْمُهَلِّ ‏ ‏قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مُهَلُّ ‏ ‏أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏مِنْ ‏ ‏ذِي الْحُلَيْفَةِ ‏ ‏وَمُهَلُّ ‏ ‏أَهْلِ الطَّرِيقِ الْأُخْرَى مِنْ ‏ ‏الْجُحْفَةِ ‏ ‏وَمُهَلُّ ‏ ‏أَهْلِ ‏ ‏الْعِرَاقِ ‏ ‏مِنْ ‏ ‏ذَاتِ عِرْقٍ ‏ ‏وَمُهَلُّ ‏ ‏أَهْلِ ‏ ‏نَجْدٍ ‏ ‏مِنْ ‏ ‏قَرْنٍ ‏ ‏وَمُهَلُّ ‏ ‏أَهْلِ ‏ ‏الْيَمَنِ ‏ ‏مِنْ ‏ ‏يَلَمْلَمَ ‏","","",""],[14089,14089,"","আমরা সবাই একটা ছেলে নিয়ে কথা বলেছি যে আমাদের সাথে কথা বলতে হবে, সে আমার ধর্ম নিয়ে কথা বলতে নিষেধ করেছে, মানুষটিকে আরো ভালো করার জন্য না পারার কারণে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَرَّمَ مَا بَيْنَ ‏ ‏حَرَّتَيْ ‏ ‏الْمَدِينَةِ ‏ ‏لَا يُقْطَعُ مِنْهَا شَجَرَةٌ إِلَّا أَنْ يَعْلِفَ الرَّجُلُ بَعِيرَهُ ‏","","",""],[14090,14090,"","আমরা একটি ছেলে কথা বলেছি যে আমাদের সাথে কথা বলেছে, তারা রাতে তোমার মৃত্যু ডেকে আনবে...","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَبِّرُوا عَلَى مَوْتَاكُمْ بِاللَّيْلِ وَالنَّهَارِ أَرْبَعَ تَكْبِيرَاتٍ ‏","","",""],[14091,14091,"","আমরা সবাই সেরা শিক্ষক হতে পেরেছি, যখন আমি তোমার শপথ নিতে চাই,","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى الْأَشْيَبُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏رَمَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْجَمْرَةَ ‏ ‏عَلَى بَعِيرِهِ بِحَصَى ‏ ‏الْخَذْفِ ‏ ‏وَهُوَ يَقُولُ ‏ ‏لِتَأْخُذُوا ‏ ‏مَنَاسِكَكُمْ ‏ ‏فَإِنِّي لَا أَدْرِي لَعَلِّي لَا أَحُجُّ بَعْدَ حَجَّتِي هَذِهِ ‏","","",""],[14092,14092,"","আমরা সবাই একটা ছেলের সাথে কথা বলেছি, যে বলল আমার ফোন কল করে ঈশ্বরের কাছে, এটা সমতার কথা। তুমি কি পরিকল্পনা করছ? ঈশ্বর তাকে ফোন করেছে","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَالَ حِينَ يُنَادِي الْمُنَادِي اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلَاةِ ‏ ‏الْقَائِمَةِ ‏ ‏صَلِّ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَارْضَ عَنْهُ رِضًا لَا تَسْخَطُ بَعْدَهُ اسْتَجَابَ اللَّهُ لَهُ دَعْوَتَهُ ‏","","",""],[14093,14093,"","আমরা সব ঠিক করেছি, আমরা একটি ছেলে কথা বলেছি আমাদের শ্বশুর আব্বা থেকে দূরে রাখার জন্য, সে সূর্যের একটা স্তর উদ্ধার করবে, আর তারপর সে হবে ঈশ্বরের সেরা সন্তান। আমি আদেশ দিচ্ছি আইন পড়তে। আমি আমার বাবার সাথে কথা বলি, আমি আমার বাবার মত আচরণ করতে। আমি যদি আমার বাবার সাথে কথা বলি, আমি আমার ছেলের সাথে কথা বলি, আমি যদি আমার বাবার মত আচরণ করি, তাহলে সে আমাকে যেতে হবে। আমি আমার বাবার সাথে আমার ছেলের মত আচরণ করতে হবে। এবং আমি আমার ছেলের সাথে কথা বলি, আমি আমার ছেলের সাথে আমার ছেলের সাথে কথা বলি, আমি আমার বাবার মত আচরণ করতে চাই। আমি যদি তুমি জানো, আমি আমার ছেলের মত আচরণ করতে পার। আমি আমার বাবার মত না। আমি আমার ছেলের নাম মেনে নিতে চাই, আমি আমার বাবা, আমি আমার বাবা, আমি আমার বাবার সাথে কথা বলি, আমি যদি তুমি জানো না। আমি আমার বাবা, আমি আমার বাবা, আমি আমার বাবা, আমি আমার বাবা, আমি আমার বাবা-মা'সই ঠিক করি। ঈশ্বরের কাছে শপথ করে বলছি, ঈশ্বর তাকে শেষ পর্যন্ত গ্রহণ করেছেন, কিন্তু আমি আদেশ করছি সে তাকে ঘৃণা করে বলে যে সে সেই নয় যে কিনা সেই নয় যে কিনা... ...যার ওপরই নির্ভর করে সে... ...যে কিনা... ঈশ্বরের দোহাই লাগে, যে ওকে ঈশ্বরের কাছে প্রার্থনা করে...","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَاهِبًا أَهْدَى لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جُبَّةَ ‏ ‏سُنْدُسٍ ‏ ‏فَلَبِسَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ أَتَى الْبَيْتَ فَوَضَعَهَا وَأَحَسَّ بِوَفْدٍ أَتَوْهُ فَأَمَرَهُ ‏ ‏عُمَرُ ‏ ‏أَنْ يَلْبَسَ ‏ ‏الْجُبَّةَ ‏ ‏لِقُدُومِ الْوَفْدِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَصْلُحُ لِبَاسُهَا لَنَا فِي الدُّنْيَا وَيَصْلُحُ لَنَا فِي الْآخِرَةِ وَلَكِنْ خُذْهَا يَا ‏ ‏عُمَرُ ‏ ‏فَقَالَ يَكْرَهُهَا وَآخَذُهَا فَقَالَ إِنِّي لَا آمُرُكَ أَنْ تَلْبَسَهَا وَلَكِنْ أَرْسِلْ بِهَا إِلَى أَرْضِ ‏ ‏فَارِسَ ‏ ‏فَتُصِيبَ بِهَا مَالًا فَأَرْسَلَ بِهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏النَّجَاشِيِّ ‏ ‏وَكَانَ قَدْ أَحْسَنَ إِلَى مَنْ فَرَّ إِلَيْهِ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[14094,14094,"","আমরা একটি ছেলে কথা বলেছি যে লর্ডের বাবা-মার সাথে কথা বলেছে, সে তার কাছে ঈশ্বরের সেবা করতে পারবে আর তার ইচ্ছা পূর্ণ করবে। আর এক গ্রীষ্মের মধ্যেই তারা তাকে উদ্ধার করবে। এমনকি ঈশ্বর তার কাছে প্রার্থনা করেছেন যদি আপনি তাকে না খেতেন, তিনি তাকে রক্ষা করতেন।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتَطْعِمُهُ فَأَطْعَمَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسْقَ ‏ ‏شَعِيرٍ فَمَا زَالَ الرَّجُلُ يَأْكُلُ مِنْهُ هُوَ وَامْرَأَتُهُ وَوَصِيفٌ لَهُمْ حَتَّى كَالُوهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ لَمْ تَكِيلُوهُ لَأَكَلْتُمْ مِنْهُ وَلَقَامَ لَكُمْ ‏","","",""],[14095,14095,"","আমরা ভালো করেই বলেছি যে আমরা ফাদার আল-জাবির সাথে কথা বলেছি... ...আমি একজন প্রতিবেশীকে জিজ্ঞেস করব, না হলে তাকে তার বাড়িতে আটকে থাকতে হবে, তাই সে আমাদের জানালো যে আমরা জানি তার এমন একজন লোক ছিল যে কিনা ঈশ্বরের গৌরবের জন্য একটা স্ট্যান্ড কিনেছিল... ...আর আল্লাহ্‌র কাছে প্রার্থনা করবে... ...আর সে আত্মসমর্পণ না করা পর্যন্ত সে তাকে শান্তি দিবে.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏أَبْصَرْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى رَاكِبًا فَقَالَ نَعَمْ ثُمَّ أَتَاهُ رَجُلٌ قَدْ اشْتَرَى نَاقَةً لِيَدْعُوَ اللَّهَ عَزَّ وَجَلَّ عَلَيْهَا فَكَلَّمَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَكَتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى سَلَّمَ ثُمَّ دَعَا لَهُ ‏","","",""],[14096,14096,"","আমরা সবাই একটা ছেলে নিয়ে কথা বলেছি ঈশ্বর সম্পর্কে কথা বলতে, আমি প্রার্থনা করতে মানুষকে ধন্যবাদ জানাতে চেয়েছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏أَشَدَّ النَّاسِ تَخْفِيفًا فِي الصَّلَاةِ ‏","","",""],[14097,14097,"","আমরা একটা ছেলের কথা বলেছিলাম, আমরা একটা ছেলের সাথে কথা বলেছিলাম, যার সাথে আমার ভালো বাবার সম্পর্ক আছে। সে বলবে, রাতে কাকে ভয় পায় না আর রাতে ঘুমোয় না। তোমার কথা শুনতে চাই। পড়, আর আমি ভাল হয়ে যাব।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ خَافَ مِنْكُمْ أَلَّا يَقُومَ بِاللَّيْلِ ‏ ‏فَلْيُوتِرْ ‏ ‏ثُمَّ يَنَامُ وَمَنْ طَمِعَ مِنْكُمْ بِقِيَامٍ ‏ ‏فَلْيُوتِرْ ‏ ‏مِنْ آخِرِ اللَّيْلِ فَإِنَّ قِرَاءَةَ آخِرِ اللَّيْلِ ‏ ‏مَحْضُورَةٌ ‏ ‏وَذَلِكَ أَفْضَلُ ‏","","",""],[14098,14098,"","আমরা একটা ছেলের কথা বলেছি যে আমাদের সাথে ঈশ্বরের দোহাই কথা বলেছে, যদি আমি তোমাকে আটকে রাখি, সে তার ডান হাতে থুতুবে...","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا بَصَقَ أَحَدُكُمْ فَلَا يَبْصُقْ عَنْ يَمِينِهِ وَلَا بَيْنَ يَدَيْهِ وَلْيَبْصُقْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ ‏","","",""],[14099,14099,"","আমরা একটা ছেলের কথা বলেছি যে আমাদের সাথে কথা বলেছে, আমি এর বেশি কিছু বলব না, সে বলবে কম্পনের মধ্যে, তুমি সেই লোক যার থেকে বেশি। কোথাও লড়াই করবে না।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكْثِرُوا مِنْ هَذِهِ النِّعَالِ فَإِنَّهُ لَا يَزَالُ أَحَدُكُمْ رَاكِبًا إِذَا انْتَعَلَ ‏ ‏وَفِي مَوْضِعٍ آخَرَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ فِي غَزْوَةٍ غَزَاهَا اسْتَكْثِرُوا مِنْ النِّعَالِ فَإِنَّ الرَّجُلَ لَا يَزَالُ رَاكِبًا مَا انْتَعَلَ ‏","","",""],[14100,14100,"","আমি আমার বাবার বাচ্চা হওয়ার ব্যাপারে কথা বলেছি, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তিনি কখনও এটা করবেন না।","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ طَلْحَةَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَارِبُوا ‏ ‏وَسَدِّدُوا ‏ ‏فَإِنَّهُ لَيْسَ أَحَدٌ مِنْكُمْ ‏ ‏يُنَجِّيهِ عَمَلُهُ قَالُوا وَلَا إِيَّاكَ يَا رَسُولَ اللَّهِ قَالَ وَلَا إِيَّايَ إِلَّا أَنْ ‏ ‏يَتَغَمَّدَنِي ‏ ‏اللَّهُ بِرَحْمَتِهِ ‏","","",""],[14101,14101,"","আমরা ঈশ্বরের ছেলের কথা বলেছিলাম যে সে আমাদের শত্রু... ...যে আমরা আমার বাবার বড় বড় বুড়োদের জন্য তৈরি করেছি, তার জন্য ঈশ্বর প্রার্থনা করেছেন আর সে তার নিজের পরবর্তী জীবনের জন্য তাকে আত্মসমর্পণ করেছে. আমি. আপনি বিশ্বাস করতে পারবেন না যে, তার দোষ তাকে অনুসরণ করতে হবে অথবা তার ইচ্ছা পালন করতে হবে ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ الَّذِي يُقَالُ لَهُ الْعَدَنِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَقَطَتْ لُقْمَةُ أَحَدِكُمْ ‏ ‏فَلْيُمِطْ ‏ ‏مَا عَلَيْهَا مِنْ أَذًى ثُمَّ لِيَأْكُلْهَا وَلَا يَدَعْهَا لِلشَّيْطَانِ وَلَا يَمْسَحْ أَحَدُكُمْ يَدَهُ بِالْمِنْدِيلِ حَتَّى يَلْعَقَ أَصَابِعَهُ ‏ ‏أَوْ يُلْعِقَهَا ‏ ‏فَإِنَّهُ لَا يَدْرِي فِي أَيِّ طَعَامِهِ الْبَرَكَةُ ‏","","",""],[14102,14102,"","আমরা তার বাবার কথা বলেছিলাম যে একজন প্রতিবেশীকে বলতে হবে যে, সে যদি তার দুর্দশার সময় মারা যায়, তাহলে তাকে আত্মসমর্পণ করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ذَكَرَ السَّاعَةَ احْمَرَّتْ ‏ ‏وَجْنَتَاهُ ‏ ‏وَاشْتَدَّ غَضَبُهُ وَعَلَا صَوْتُهُ كَأَنَّهُ مُنْذِرُ جَيْشٍ صُبِّحْتُمْ مُسِّيتُمْ ‏","","",""],[14103,14103,"","সে বলেছিল আমরা টাকা সঞ্চয় করছিলাম আর কে সবসময় নিরাপদ ছিল.","‏ ‏قَالَ ‏ ‏وَكَانَ يَقُولُ ‏ ‏أَنَا أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ وَمَنْ تَرَكَ مَالًا فَلِأَهْلِهِ وَمَنْ تَرَكَ دَيْنًا أَوْ ضَيَاعًا فَإِلَيَّ وَعَلَيَّ وَأَنَا أَوْلَى بِالْمُؤْمِنِينَ ‏","","",""],[14104,14104,"","ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং আমাকে চুপ থাকতে বলেন না । কোর্ট বা মিথ্যা কথা বলে, এমনকি যদি এটা রীতিও হত।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَغَيْرُهُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُجَالِدٌ ‏ ‏عَنْ ‏ ‏عَامِرٍ الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَسْأَلُوا ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏عَنْ شَيْءٍ فَإِنَّهُمْ لَنْ يَهْدُوكُمْ وَقَدْ ضَلُّوا فَإِنَّكُمْ إِمَّا أَنْ تُصَدِّقُوا بِبَاطِلٍ أَوْ تُكَذِّبُوا بِحَقٍّ فَإِنَّهُ لَوْ كَانَ ‏ ‏مُوسَى ‏ ‏حَيًّا بَيْنَ أَظْهُرِكُمْ مَا حَلَّ لَهُ إِلَّا أَنْ يَتَّبِعَنِي ‏","","",""],[14105,14105,"","দুই দৌড়বিদ হচ্ছে সেই শিকারীর ছেলে, যারা সিংহাসনে মিলিত হয়েছে এবং বলে যে, এটা করা উচিত নয় । আমি জানতাম যে, আমি যদি যিহোবার কাছে প্রার্থনা করি, তা হলে তিনি আমাকে ক্ষমা করবেন ।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَسَعَ ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏رَجُلًا ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَاجْتَمَعَ قَوْمُ ذَا وَقَوْمُ ذَا وَقَالَ هَؤُلَاءِ يَا ‏ ‏لَلْمُهَاجِرِينَ ‏ ‏وَقَالَ هَؤُلَاءِ يَا ‏ ‏لَلْأَنْصَارِ ‏ ‏فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏دَعُوهَا فَإِنَّهَا مُنْتِنَةٌ قَالَ ثُمَّ قَالَ أَلَا مَا بَالُ دَعْوَى أَهْلِ الْجَاهِلِيَّةِ أَلَا مَا بَالُ دَعْوَى أَهْلِ الْجَاهِلِيَّةِ ‏","","",""],[14106,14106,"","আমরা হামাদের কথা বলেছি, একজন প্রতিবেশীর এক বছরের দাঙ্গার মানে হচ্ছে যে বলত সে বলবে, আল্লাহকে আত্মসমর্পণ করতে হবে, আপনাকে তার বাবা আর মেয়ের জন্ম দিতে হবে না।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُنْكَحُ الْمَرْأَةُ عَلَى عَمَّتِهَا وَلَا عَلَى خَالَتِهَا وَلَا الْمَرْأَةُ عَلَى ابْنَةِ أَخِيهَا وَلَا عَلَى ابْنَةِ أُخْتِهَا ‏","","",""],[14107,14107,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমার সমস্ত মহৎ জ্ঞান ও শক্তির প্রতি নিজেকে উৎসর্গ করেছেন বন্ধুরা, ষড়যন্ত্রকারী তাপ।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِكُلِّ نَبِيٍّ ‏ ‏حَوَارِيٌّ ‏ ‏وَحَوَارِيَّ ‏ ‏الزُّبَيْرُ ‏ ‏قَالَ ‏ ‏سَمِعْت ‏ ‏سُفْيَانَ بْنَ عُيَيْنَةَ ‏ ‏يَقُولُ ‏ ‏الْحَوَارِيُّ ‏ ‏النَّاصِرُ ‏","","",""],[14108,14108,"","আমরা একটা বাপ্তিস্মের কথা বলেছিলাম যার মানে ছিল একজন জে এর ছেলে যে একটা কাপুরুষের ছেলে বলেছে যে সে একটা কুত্তার বাচ্চা অসুস্থ হয়ে যাওয়া ঘৃণা.","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ دِينَارٍ ‏ ‏يَقُولُ عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏كِرَاءِ ‏ ‏الْأَرْضِ ‏","","",""],[14109,14109,"","ঈশ্বর তাঁর কাছে প্রার্থনা করেছিলেন এবং যারা মারা গিয়েছে তাদের কাছে আত্মসমর্পণ করেছিলেন এবং তিনি হয়তো মারা গিয়েছিলেন ও আমার মাকে কী খেতে হয়েছিল, তা আমি খুবই হতাশ হয়ে পড়েছিলাম । পবিত্র পিতার বলা হয়েছে যে আমার বাবা একজন শপথী পিতা হতে চান।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏وَهْبِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَحْيَا أَرْضًا مَيْتَةً فَهِيَ لَهُ وَمَا أَكَلَتْ ‏ ‏الْعَافِيَةُ ‏ ‏فَهُوَ لَهُ ‏ ‏صَدَقَةٌ ‏ ‏فَقَالَ ‏ ‏رَجُلٌ ‏ ‏يَا ‏ ‏أَبَا الْمُنْذِرِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏أَبُو الْمُنْذِرِ هِشَامُ بْنُ عُرْوَةَ ‏ ‏مَا ‏ ‏الْعَافِيَةُ ‏ ‏قَالَ ‏ ‏مَا اعْتَافَهَا مِنْ شَيْءٍ ‏","","",""],[14110,14110,"","আমরা ভাল কথা বলেছি, কিন্তু আমরা একটা জাদু করেছি যার মানে আমার বাবার বয়স যখন শেষ হবে তখন তার ছেলে কাপুরুষের মত মারা যাবে, ঈশ্বর তাকে উদ্ধার করতে হবে আর আমি তাদের কাছে সবচেয়ে বড় হব। ঘুম থেকে তুমি চাইলে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ أَبِي عَمَّارٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏أَتَانِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏فَأَطْعَمْتُهُمْ رُطَبًا وَأَسْقَيْتُهُمْ مَاءً فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا مِنْ النَّعِيمِ الَّذِي تُسْأَلُونَ عَنْهُ ‏","","",""],[14111,14111,"","আমরা একটা ছেলে ছেলের কথা বলেছিলাম যে কিনা তোমাকে ঈশ্বরের দোহাই দিয়ে কিনতে চেয়েছিল, কিন্তু আমি কেন ঈশ্বরের কাছে প্রার্থনা করব আর তাকে বলতে হবে যে, তাকে অবশ্যই তা করতে হবে। তুমি আমাকে বলো তুমি আমার কী হবে, আমি এটা ভুলবো না, ভবিষ্যদ্বাণীর মাত্রা আমার হয়ে যাবে.","‏ ‏حَدَّثَنَا ‏ ‏شَاذَانُ أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا أَرَادَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُخَلِّفَ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ قَالَ لَهُ ‏ ‏عَلِيٌّ ‏ ‏مَا يَقُولُ النَّاسُ فِيَّ إِذَا ‏ ‏خَلَّفْتَنِي ‏ ‏قَالَ فَقَالَ ‏ ‏مَا ‏ ‏تَرْضَى أَنْ تَكُونَ مِنِّي بِمَنْزِلَةِ ‏ ‏هَارُونَ ‏ ‏مِنْ ‏ ‏مُوسَى ‏ ‏إِلَّا أَنَّهُ لَيْسَ بَعْدِي نَبِيٌّ ‏ ‏أَوْ لَا يَكُونُ بَعْدِي نَبِيٌّ ‏","","",""],[14112,14112,"","আমরা হামাদ বানের স্বপ্নের কথা বলেছি আমার বড় ভাই বলছে সে ঈশ্বরের জন্য প্রার্থনা করছে, পানি বিক্রির জন্য তাকে হস্তান্তর করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ فَضْلِ الْمَاءِ ‏","","",""],[14113,14113,"","আমরা আমার বাবা, ঐ ছেলে, সে বলেছিল, \"ঈশ্বর,\" ঈশ্বর আমাকে ছেড়ে দিতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَمُوسَى بْنُ دَاوُدَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ الْأَرْضِ الْبَيْضَاءِ سَنَتَيْنِ أَوْ ثَلَاثًا ‏","","",""],[14114,14114,"","আমরা সব ঠিক বলেছি আর আমার মনে হয় তুমি হয়তো আমার সহকর্মীর ব্যাপারে কিছু একটা করেছ। আমরা তার বাবার সাথে কথা বলেছি যে আমি ঈশ্বরের দোহাই দিয়ে যাচ্ছি আর সে আমার পালা ঘুরিয়ে দেবে। একপাশে সে মাটিতে নেমে আসবে, সে নিজের জীবন একটা রসুনের মত দেখে... ...অথবা একটা গ্যাপের মতো, সে নিজের কথা ভুলে যেতে পারে। তার ব্ল্যাকস্মিথ বলেছে সে করেনি.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَأَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏أَحْمَدُ ‏ ‏فِي حَدِيثِهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأَبِي قُحَافَةَ ‏ ‏أَوْ جَاءَ عَامَ الْفَتْحِ ‏ ‏وَرَأْسُهُ وَلِحْيَتُهُ مِثْلُ ‏ ‏الثَّغَامِ ‏ ‏أَوْ مِثْلُ ‏ ‏الثَّغَامَةِ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏فَأَمَرَ بِهِ إِلَى نِسَائِهِ ‏ ‏قَالَ ‏ ‏غَيِّرُوا هَذَا الشَّيْبَ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏قَالَ ‏ ‏زُهَيْرٌ ‏ ‏قُلْتُ ‏ ‏لِأَبِي الزُّبَيْرِ ‏ ‏أَقَالَ جَنِّبُوهُ السَّوَادَ قَالَ لَا ‏","","",""],[14115,14115,"","আমরা আমার বাবার প্রিয় বন্ধুর কথা বলেছি যে আমাকে ঈশ্বরের ইচ্ছার কাছে পাঠিয়েছে। সে একজন ভালো যোদ্ধা। তারপর আমি তাকে বললাম, তার হাত আমার কাছে আছে, আর আমি শুনতে চাই। এটা পড়ে আমি পড়েছি, আমি তোমাকে প্রার্থনা করতে বলতে চাইনি।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏أَرْسَلَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُنْطَلِقٌ إِلَى ‏ ‏بَنِي الْمُصْطَلِقِ ‏ ‏فَأَتَيْتُهُ وَهُوَ ‏ ‏يُصَلِّي عَلَى بَعِيرِهِ فَكَلَّمَتْهُ فَقَالَ بِيَدِهِ هَكَذَا ‏ ‏وَأَشَارَ ‏ ‏زُهَيْرٌ ‏ ‏بِكَفِّهِ ‏ ‏ثُمَّ كَلَّمْتُهُ فَقَالَ بِيَدِهِ هَكَذَا وَأَنَا ‏ ‏أَسْمَعُهُ يَقْرَأُ ‏ ‏وَيُومِئُ ‏ ‏بِرَأْسِهِ فَلَمَّا فَرَغَ قَالَ مَا فَعَلْتَ فِي الَّذِي أَرْسَلْتُكَ لَهُ فَإِنَّهُ ‏ ‏لَمْ يَمْنَعْنِي أَنْ أُكَلِّمَكَ إِلَّا أَنِّي كُنْتُ أُصَلِّي ‏","","",""],[14116,14116,"","আমরা আমার বাবার কথা বলেছি, একটা ছেলে খুঁজে বের করার চেষ্টা করছে, তার কাছে শান্তি আছে আর সে জিজ্ঞেস করছে কার মন আছে।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏حَسَنُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَانَ لَهُ إِمَامٌ فَقِرَاءَتُهُ لَهُ قِرَاءَةٌ ‏","","",""],[14117,14117,"","আমরা হামাদ বানের স্বপ্নের কথা বলেছি আমার বাবা বলেছেন তিনি ঈশ্বরের জন্য প্রার্থনা করছেন, পানি বিক্রির জন্য তাকে হস্তান্তর করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ فَضْلِ الْمَاءِ ‏","","",""],[14118,14118,"","আমরা ঈশ্বরের বার্তাবাহকের কাছে গিয়ে তার কাছে প্রার্থনা করেছিলাম আর তারপর আমরা শান্ত হয়ে গেলাম।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏غَزَوْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَصَبْنَا جَرَادًا فَأَكَلْنَاهُ ‏","","",""],[14119,14119,"","আমরা একটা কুকুর ছেলে কথা বলেছি যে আমাকে কাস্টমারের বাবাকে বলেছিল যে সে উত্তর পেয়েছে যুবক।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُقْتَلَ شَيْءٌ مِنْ الدَّوَابِّ صَبْرًا ‏","","",""],[14120,14120,"","আমরা একটা অপরাধবাজ ছেলের কথা বলেছি যে আমাকে বলেছিল যে সে ঈশ্বরের উত্তর শুনেছে, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর সে মানুষের হিসাবর উপর আত্মসমর্পণ করবে শিরোনাম অথবা শর্টকাটটি হারিয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يَقْعُدَ الرَّجُلُ عَلَى الْقَبْرِ أَوْ ‏ ‏يُقَصَّصَ ‏ ‏أَوْ ‏ ‏يُبْنَى عَلَيْهِ ‏","","",""],[14121,14121,"","ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং তিনি বৃক্ষগুলোকে উদ্ধার করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الشِّغَارِ ‏","","",""],[14122,14122,"","আমরা একটি ছেলে থাকার চেয়ে একটি ছেলেকে ভালো কিছু খুঁজে পাওয়ার ব্যাপারে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَشْعَثَ بْنِ سَوَّارٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَدْخُلُ مَسْجِدَنَا هَذَا مُشْرِكٌ بَعْدَ عَامِنَا هَذَا غَيْرَ ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏وَخَدَمِهِمْ ‏","","",""],[14123,14123,"","মানুষ বলে এটা নিষিদ্ধ যদি তারা বলে এটা নিষিদ্ধ।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏رَفَعَ الْحَدِيثَ قَالَ ‏ ‏أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا لَا إِلَهَ إِلَّا اللَّهُ فَإِذَا قَالُوهَا حَرُمَتْ عَلَيَّ دِمَاؤُهُمْ وَأَمْوَالُهُمْ وَعَلَى اللَّهِ حِسَابُهُمْ ‏ ‏أَوْ وَحِسَابُهُمْ عَلَى اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[14124,14124,"","ঈশ্বরের আদেশ পালন করতে গিয়ে আমার শ্বশুর আব্বার সাথে কথা বলেছি। ঈশ্বর ও অন্যান্য জগৎ তাঁর সঙ্গে নেই এমন একজন মহিলাকে কখনোই ছেড়ে দেবেন না ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا يَدْخُلْ الْحَمَّامَ إِلَّا ‏ ‏بِمِئْزَرٍ ‏ ‏وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا يُدْخِلْ ‏ ‏حَلِيلَتَهُ ‏ ‏الْحَمَّامَ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا يَقْعُدْ عَلَى مَائِدَةٍ يُشْرَبُ عَلَيْهَا الْخَمْرُ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا يَخْلُوَنَّ بِامْرَأَةٍ لَيْسَ مَعَهَا ذُو ‏ ‏مَحْرَمٍ ‏ ‏مِنْهَا فَإِنَّ ثَالِثَهُمَا الشَّيْطَانُ ‏","","",""],[14125,14125,"","আমরা একটা ছেলেকে মুছে ফেলার চেষ্টা করেছি, আমার শ্বশুর আব্বা সম্পর্কে কথা বলেছি। ভালো খবর হচ্ছে, সে তার জন্য প্রার্থনা করছে। আর সে এটা দিয়ে দেবে কুকুরের পরবর্তীটার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏و عَنْ ‏ ‏خَيْرِ بْنِ نُعَيْمٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ثَمَنِ الْكَلْبِ وَنَهَى عَنْ ثَمَنِ السِّنَّوْرِ ‏","","",""],[14126,14126,"","আমরা আমাদের সময় মুছে ফেলার চেষ্টা করেছি, কিন্তু তারপর আমি আমার সাথে কথা বলেছি, কিন্তু ঈশ্বর তার কাছে প্রার্থনা করেছেন যে তিনি তার জীবন সমর্পণ করেছেন, বিষ বিক্রি করে দেন এবং তোমাকে বিয়ে করতে হবে। ''আর যে আমাকে আদেশ করবে সে নিশ্চয়ই হবে যিনি আমাকে রক্ষা করবে বিশ্বস্তভাবে যার কাছে সে হবে একজন সাহায্যকারী।’’ সেই ব্যক্তি হবেন সেই ব্যক্তি, যে হবে সেই হবে সেই ব্যক্তি, যে আমার রাজা হবে। কেউ তাকে জোর করে ধরে নিয়ে আসে, এমনকি যদি সে ক্ষতি থেকে মুক্তি পাওয়ার অধিকার থেকে মুক্ত হয় অথবা অধিকার থেকে মুক্ত হওয়ার অধিকার থেকে তাকে মুক্ত করে দেয়। তারা বলবে, হাঙ্গর তোমাকে খুঁজে পাবে না, আর তারা তোমাকে খুঁজে পাবে না। আমরা কথা দিচ্ছি, ঈশ্বর তার কাছে যে তাকে জিততে পারবেন, তারও বিশ্বাস করা উচিত। একটা ষাঁড়ের বাড়ি যেটা পৃথিবীকে উড়িয়ে দেবে না, আমরা আমাদের থেকে একজন মানুষকে বিক্রি করে দেবো যতক্ষণ না আমরা দেখতে পাই যে কিভাবে ঈশ্বর কিভাবে উদ্ধার করেছেন আমরা তার নামে তার সাথে দেখা হওয়া পর্যন্ত সেখানে গিয়েছিলাম। আপনার কাছে যে শক্তি ছিল তা হল, আমাদের একজন মানুষ প্রয়োজন ছিল। আমাদের দিকে যার পাঠানো হয়েছে, তারা বলেছে যে আমি তাদের জানি না, কিন্তু ঈশ্বর তোমাকেও দেবেন। ঈশ্বর তোমাকে কয়েক বছর ধরে তার হাতে তুলে দেবেন না... ...এই জোর দিয়ে যে তুমি আমাকে জিততে পারবে. আমি তোমাকে আর পাগল বানিয়ে দিব... ...আমি তোমাকে বিক্রি করতে হবে আমি তার হাত তুলে নেব আর আমি বোতামের বোতামটা নিয়ে নিতে চাই আর সেটা আমি তাকে এটা বিক্রি করতে হবে আমরা তাকে এভাবে হারাতে দেখিনি, যতক্ষণ পর্যন্ত আমরা জানতাম সে মারা যাবে। তোমার ইচ্ছা হচ্ছে তোমাকে কামড় দেওয়া হবে, তাকেও দেওয়া হবে। ক্ষমা এবং পাপ, ভয় পাওয়ার ভয়ে ভয় পাই, আমরা আমাদের নিজেদের উপরে দিয়ে যাচ্ছি যদি আমরা ওখানে না যাই আর তাকে মেরে ফেলবো।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏أَنَّهُ حَدَّثَهُ ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَبِثَ عَشْرَ سِنِينَ يَتَّبِعُ الْحَاجَّ فِي مَنَازِلِهِمْ فِي الْمَوْسِمِ ‏ ‏وَبِمَجَنَّةٍ ‏ ‏وَبِعُكَاظٍ ‏ ‏وَبِمَنَازِلِهِمْ ‏ ‏بِمِنًى ‏ ‏مَنْ ‏ ‏يُؤْوِينِي مَنْ يَنْصُرُنِي حَتَّى أُبَلِّغَ رِسَالَاتِ رَبِّي عَزَّ وَجَلَّ وَلَهُ الْجَنَّةُ فَلَا يَجِدُ أَحَدًا يَنْصُرُهُ ‏ ‏وَيُؤْوِيهِ حَتَّى إِنَّ الرَّجُلَ يَرْحَلُ مِنْ ‏ ‏مُضَرَ ‏ ‏أَوْ مِنْ ‏ ‏الْيَمَنِ ‏ ‏أَوْ ‏ ‏زَوْرِ صَمَدٍ ‏ ‏فَيَأْتِيهِ قَوْمُهُ فَيَقُولُونَ احْذَرْ غُلَامَ ‏ ‏قُرَيْشٍ ‏ ‏لَا يَفْتِنُكَ وَيَمْشِي بَيْنَ ‏ ‏رِحَالِهِمْ ‏ ‏يَدْعُوهُمْ إِلَى اللَّهِ عَزَّ وَجَلَّ يُشِيرُونَ إِلَيْهِ بِالْأَصَابِعِ حَتَّى بَعَثَنَا اللَّهُ عَزَّ وَجَلَّ لَهُ مِنْ ‏ ‏يَثْرِبَ ‏ ‏فَيَأْتِيهِ الرَّجُلُ فَيُؤْمِنُ بِهِ فَيُقْرِئُهُ الْقُرْآنَ فَيَنْقَلِبُ إِلَى أَهْلِهِ فَيُسْلِمُونَ بِإِسْلَامِهِ حَتَّى لَا ‏ ‏يَبْقَى دَارٌ مِنْ دُورِ ‏ ‏يَثْرِبَ ‏ ‏إِلَّا فِيهَا ‏ ‏رَهْطٌ ‏ ‏مِنْ الْمُسْلِمِينَ يُظْهِرُونَ الْإِسْلَامَ ثُمَّ بَعَثَنَا اللَّهُ عَزَّ وَجَلَّ فَأْتَمَرْنَا وَاجْتَمَعْنَا سَبْعُونَ رَجُلًا مِنَّا فَقُلْنَا حَتَّى مَتَى ‏ ‏نَذَرُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُطْرَدُ فِي جِبَالِ ‏ ‏مَكَّةَ ‏ ‏وَيَخَافُ فَدَخَلْنَا حَتَّى قَدِمْنَا عَلَيْهِ فِي الْمَوْسِمِ فَوَاعَدْنَاهُ شِعْبَ ‏ ‏الْعَقَبَةِ ‏ ‏فَقَالَ عَمُّهُ ‏ ‏الْعَبَّاسُ ‏ ‏يَا ابْنَ أَخِي إِنِّي لَا أَدْرِي مَا هَؤُلَاءِ الْقَوْمُ الَّذِينَ جَاءُوكَ إِنِّي ذُو مَعْرِفَةٍ بِأَهْلِ ‏ ‏يَثْرِبَ ‏ ‏فَاجْتَمَعْنَا عِنْدَهُ مِنْ رَجُلٍ وَرَجُلَيْنِ فَلَمَّا نَظَرَ ‏ ‏الْعَبَّاسُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فِي وُجُوهِنَا قَالَ هَؤُلَاءِ قَوْمٌ لَا أَعْرِفُهُمْ هَؤُلَاءِ أَحْدَاثٌ فَقُلْنَا يَا رَسُولَ اللَّهِ عَلَامَ ‏ ‏نُبَايِعُكَ ‏ ‏قَالَ ‏ ‏تُبَايِعُونِي ‏ ‏عَلَى السَّمْعِ ‏ ‏وَالطَّاعَةِ فِي النَّشَاطِ وَالْكَسَلِ وَعَلَى النَّفَقَةِ فِي الْعُسْرِ وَالْيُسْرِ وَعَلَى الْأَمْرِ بِالْمَعْرُوفِ وَالنَّهْيِ عَنْ الْمُنْكَرِ وَعَلَى أَنْ تَقُولُوا فِي اللَّهِ لَا تَأْخُذُكُمْ فِيهِ لَوْمَةُ لَائِمٍ وَعَلَى أَنْ تَنْصُرُونِي إِذَا قَدِمْتُ ‏ ‏يَثْرِبَ ‏ ‏فَتَمْنَعُونِي مِمَّا تَمْنَعُونَ مِنْهُ أَنْفُسَكُمْ وَأَزْوَاجَكُمْ وَأَبْنَاءَكُمْ وَلَكُمْ الْجَنَّةُ فَقُمْنَا نُبَايِعُهُ فَأَخَذَ بِيَدِهِ ‏ ‏أَسْعَدُ بْنُ زُرَارَةَ ‏ ‏وَهُوَ أَصْغَرُ السَّبْعِينَ فَقَالَ رُوَيْدًا يَا أَهْلَ ‏ ‏يَثْرِبَ ‏ ‏إِنَّا لَمْ نَضْرِبْ إِلَيْهِ أَكْبَادَ ‏ ‏الْمَطِيِّ ‏ ‏إِلَّا وَنَحْنُ نَعْلَمُ أَنَّهُ رَسُولُ اللَّهِ إِنَّ إِخْرَاجَهُ الْيَوْمَ مُفَارَقَةُ ‏ ‏الْعَرَبِ ‏ ‏كَافَّةً وَقَتْلُ خِيَارِكُمْ وَأَنْ تَعَضَّكُمْ السُّيُوفُ فَإِمَّا أَنْتُمْ قَوْمٌ تَصْبِرُونَ عَلَى السُّيُوفِ إِذَا مَسَّتْكُمْ وَعَلَى قَتْلِ خِيَارِكُمْ وَعَلَى مُفَارَقَةِ ‏ ‏الْعَرَبِ ‏ ‏كَافَّةً فَخُذُوهُ وَأَجْرُكُمْ عَلَى اللَّهِ عَزَّ وَجَلَّ وَإِمَّا أَنْتُمْ قَوْمٌ تَخَافُونَ مِنْ أَنْفُسِكُمْ خِيفَةً فَذَرُوهُ فَهُوَ ‏ ‏أَعْذَرُ عِنْدَ اللَّهِ قَالُوا يَا ‏ ‏أَسْعَدُ بْنَ زُرَارَةَ ‏ ‏أَمِطْ ‏ ‏عَنَّا يَدَكَ فَوَاللَّهِ لَا ‏ ‏نَذَرُ ‏ ‏هَذِهِ الْبَيْعَةَ وَلَا ‏ ‏نَسْتَقِيلُهَا ‏ ‏فَقُمْنَا إِلَيْهِ رَجُلًا رَجُلًا يَأْخُذُ عَلَيْنَا بِشُرْطَةِ ‏ ‏الْعَبَّاسِ ‏ ‏وَيُعْطِينَا عَلَى ذَلِكَ الْجَنَّةَ ‏","","",""],[14127,14127,"","আমরা বাবার সুন্দর চেহারার ছেলেকে ঈশ্বরের কাছে ডাকতে বলেছিলাম, যদি আমার সহ-জনরা আমার প্রার্থনা ভুলে যায়...","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا أَنْسَانِي الشَّيْطَانُ شَيْئًا مِنْ صَلَاتِي فَلْيُسَبِّحْ الرِّجَالُ وَلْيُصَفِّقْ النِّسَاءُ ‏","","",""],[14128,14128,"","আমার বাবার এই বাজে উত্তর সম্পর্কে আমরা কথা বলেছিলাম যে আমার ছেলে আমাকে বলতে হবে এবং আমি মানুষের ক্ষতবিক্ষত একটা ক্যারিয়ারে পরিণত করব।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَفَّ النَّاسِ صَلَاةً فِي تَمَامٍ ‏","","",""],[14129,14129,"","আমরা একটা ভুল করার চেষ্টা করেছি। কেন সে ঈশ্বরের সর্বোচ্চ প্রভু হতে পারে তা নিয়ে কথা বলেছি। সে তার ছেলে হবে সবচেয়ে দ্রুত।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ يَوْمُ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏أَهْرَاقَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْخَمْرَ وَكَسَرَ جِرَارَهُ وَنَهَى عَنْ بَيْعِهِ وَبَيْعِ الْأَصْنَامِ ‏","","",""],[14130,14130,"","আমার বাবার অকালজাত উত্তর সম্পর্কে আমরা কথা বলেছিলাম, ঈশ্বর জিজ্ঞাসা করতে বলায়। যদি আমার বাবা মা থাকত তাহলে তার বাবা-মা'র বাবা হত, আমি একজন বাবা হতাম। চেষ্টা করবে না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ أَنَّ لِابْنِ ‏ ‏آدَمَ ‏ ‏وَادِيًا مِنْ مَالٍ لَتَمَنَّى وَادِيَيْنِ وَلَوْ أَنَّ لَهُ وَادِيَيْنِ لَتَمَنَّى ثَالِثًا وَلَا يَمْلَأُ جَوْفَ ابْنِ ‏ ‏آدَمَ ‏ ‏إِلَّا التُّرَابُ ‏","","",""],[14131,14131,"","আমরা একটা উপহার নিয়ে কথা বলেছি, আমাদের বলার জন্য যে আমরা তোমাকে দাম দিচ্ছি। দয়া করে একটু শান্ত হও।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَطَاءٍ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْرَائِيلُ بْنُ يُونُسَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَفَرَ اللَّهُ لِرَجُلٍ كَانَ مِنْ قَبْلِكُمْ سَهْلًا إِذَا بَاعَ سَهْلًا إِذَا اشْتَرَى سَهْلًا إِذَا قَضَى سَهْلًا إِذَا اقْتَضَى ‏","","",""],[14132,14132,"","ঈশ্বর তাকে উদ্ধার করতে বলেছিলেন । মসজিদ আর তোমার ঈশ্বরের কাছে তোমার হাত আছে।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَنَامُ حَتَّى يَقْرَأَ ‏ ‏الم تَنْزِيلُ السَّجْدَةَ ‏ ‏وَتَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ ‏","","",""],[14133,14133,"","আমরা বাবা মাকে মারার চেষ্টা করতাম অথবা তার সাথে কথা বলার চেষ্টা করতাম। ঈশ্বরের দোহাই থেকে তিনি বলেছিলেন, আমরা ঈশ্বরের সাথে এসেছি, তিনি এটা সহজে করেছেন। তিনি তিন বার লাথি মেরে বেরিয়ে এসেছিলেন। ...আর চলে গেল.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ يَعْنِي ابْنَ بِلَالٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَوْ ‏ ‏حَدَّثَهُ ‏ ‏جَعْفَرُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏سَمِعَهُ مِنْهُ ‏ ‏قَالَ ‏ ‏قَدِمْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَكَّةَ ‏ ‏قَالَ ‏ ‏فَطَافَ سَبْعًا وَرَمَلَ مِنْهَا ثَلَاثًا وَمَشَى أَرْبَعًا ‏","","",""],[14134,14134,"","ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তিনি এমনকি কয়েক বার সেখান থেকে হেঁটে চলে গেছেন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَدَأَ بِالْحَجَرِ فَرَمَلَ حَتَّى عَادَ إِلَيْهِ ثَلَاثًا وَمَشَى أَرْبَعًا ‏","","",""],[14135,14135,"","আমরা সবাই চেষ্টা করার জন্য দোষী, ঈশ্বরের কাছে প্রার্থনা করতে চাই তিনি স্বর্গ আর স্বর্গের আনন্দ কামনা করেছেন, আর ছেলেটা ঠিক আছে।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ قَرْمٍ ‏ ‏عَنْ ‏ ‏أَبِي يَحْيَى الْقَتَّاتِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِفْتَاحُ الْجَنَّةِ الصَّلَاةُ وَمِفْتَاحُ الصَّلَاةِ الطُّهُورُ ‏ ‏هَكَذَا وَقَعَ فِي الْأَصْلِ ‏ ‏حَسَنٌ ‏ ‏وَالصَّوَابُ ‏ ‏حُسَيْنٌ ‏","","",""],[14136,14136,"","আমরা একটা ছেলের কথা বলেছিলাম, ঈশ্বর আমাদের কথা বলেছেন। সে ByzoM কে তার সাথে বসতে ইচ্ছুক এবং বলবে তিনিই সেই ব্যক্তি, যে ছিল সেই ব্যক্তি, যে কিনা কিনা যে কিনা প্রচণ্ডভাবে আঘাত পেয়েছিল।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَوْمِ عَاشُورَاءَ ‏ ‏أَنْ نَصُومَهُ وَقَالَ هُوَ يَوْمٌ كَانَتْ ‏ ‏الْيَهُودُ ‏ ‏تَصُومُهُ ‏","","",""],[14137,14137,"","ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং আমরা তাকে যেতে বলব । এমনকি তিনি আটকে পড়েছিলেন এবং বলেছিলেন যে, ঈশ্বর তাঁর কাছে আসেন এবং বলেন, আপনার একটা আসন আছে ।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ ‏ ‏أُمَّ مَالِكٍ الْبَهْزِيَّةَ ‏ ‏كَانَتْ ‏ ‏تُهْدِي فِي ‏ ‏عُكَّةٍ ‏ ‏لَهَا سَمْنًا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَيْنَا بَنُوهَا يَسْأَلُونَهَا ‏ ‏الْإِدَامَ ‏ ‏وَلَيْسَ عِنْدَهَا شَيْءٌ ‏ ‏فَعَمَدَتْ إِلَى ‏ ‏عُكَّتِهَا ‏ ‏الَّتِي كَانَتْ ‏ ‏تُهْدِي فِيهَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَجَدَتْ فِيهَا سَمْنًا فَمَا زَالَ يَدُومُ لَهَا ‏ ‏أُدْمُ ‏ ‏بَنِيهَا حَتَّى عَصَرَتْهُ وَأَتَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَعَصَرْتِيهِ قَالَتْ نَعَمْ قَالَ لَوْ ‏ ‏تَرَكْتِيهِ مَا ‏ ‏زَالَ ذَلِكَ لَكِ مُقِيمًا ‏","","",""],[14138,14138,"","আমরা সবাই কথা বলেছি, আমরা ইতিমধ্যেই ভালো বাবার ব্যাপারে কথা বলেছি, যদি একজন মায়ের ছেলে অন্য কোন কথা শুনতে পারত, সে ঈশ্বরকে শুনতে পেত, আর যদি বলত সে তার ছেলে কত কথা শুনেছে। একজন মা তার মত পছন্দ করে এবং তারপর তার বাবার জন্য, এমনকি তার মায়ের জন্য ইচ্ছাও করে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ ‏ ‏جَابِرًا ‏ ‏أَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كَانَ لِابْنِ ‏ ‏آدَمَ ‏ ‏وَادٍ تَمَنَّى آخَرَ فَقَالَ ‏ ‏جَابِرٌ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَوْ كَانَ لِابْنِ ‏ ‏آدَمَ ‏ ‏وَادٍ مِنْ نَخْلٍ تَمَنَّى مِثْلَهُ ثُمَّ تَمَنَّى مِثْلَهُ حَتَّى يَتَمَنَّى أَوْدِيَةً وَلَا يَمْلَأُ جَوْفَ ابْنِ ‏ ‏آدَمَ ‏ ‏إِلَّا التُّرَابُ ‏","","",""],[14139,14139,"","আমরা সবাই আমার বাবা সম্পর্কে কথা বলেছি, আমরা তার ঊর্ধ্বতন পিতা সম্পর্কে কথা বলেছি, এবং তিনি তার হাত তার মাথার উপর পেয়েছিলাম. যখন আকাশ এবং দশ ফিরে আসা হবে, সূর্য পড়ে যাবে. দশম।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فِيمَا سَقَتْ السَّمَاءُ وَالْعُيُونُ الْعُشْرُ وَفِيمَا سَقَتْ ‏ ‏السَّانِيَةُ ‏ ‏نِصْفُ الْعُشْرِ ‏","","",""],[14140,14140,"","তিনি ঈশ্বরের কাছে প্রার্থনা করেন তিনি বলেন যে তিনি যখন হ্রাস এবং মেঘ, অর্ধেক হবে, তখন তিনি কি করবেন বাসাটা।","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يُذْكَرُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فِيمَا سَقَتْ الْأَنْهَارُ ‏ ‏وَالْغَيْمُ ‏ ‏الْعُشُورُ وَفِيمَا سَقَتْ ‏ ‏السَّانِيَةُ ‏ ‏نِصْفُ الْعُشُورِ ‏","","",""],[14141,14141,"","আমরা একটা ছেলের কথা বলেছি যে আমাদের সাথে কথা বলেছে তার অকালমৃত্যুর উত্তর সম্পর্কে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏زَجَرَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُبَالَ فِي الْمَاءِ ‏ ‏الرَّاكِدِ ‏","","",""],[14142,14142,"","আমরা একটি ছেলে কথা বলেছি যে প্রভুর বাবা-মার সাথে কথা বলেছে, সে বলেছিল আমরা হয়তো এমন এক যুবকের সাথে সেক্স করতে চাই যে তার সাথে তার মত ব্যবহার করবে আগুন থেকে আর এটা আমার জন্য জয়।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَالَ رَبُّنَا عَزَّ وَجَلَّ ‏ ‏الصِّيَامُ جُنَّةٌ يَسْتَجِيرُ بِهَا الْعَبْدُ مِنْ النَّارِ وَهُوَ لِي وَأَنَا أَجْزِي بِهِ ‏","","",""],[14143,14143,"","আমরা ভালো করেই বলেছি যে, আমরা একটা ছেলেকে কথা বলেছি... ...আমাদের বিভ্রান্ত করার জন্য... ...যে কিনা এক প্রতিবেশীর কাছে জিজ্ঞেস করবে যে সে লর্ডের কথা শুনেছে কিনা। সে বলবে তুমি পারবে না। সে যদি ভয় পায় তাহলে সে ব্যর্থ হবে। ঈশ্বর তার নারীদের এক মাস সময় দিয়েছেন, আমরা তার ক্ষমতা বাড়িয়েছি এবং বলে যে, মাস দিন দিন বেড়ে যাচ্ছে এবং খারাপ হচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏هَلْ سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَصُومُوا حَتَّى تَرَوْا الْهِلَالَ فَإِنْ خَفِيَ عَلَيْكُمْ فَأَتِمُّوا ثَلَاثِينَ وَقَالَ ‏ ‏جَابِرٌ ‏ ‏هَجَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِسَاءَهُ شَهْرًا فَنَزَلَ لِتِسْعٍ وَعِشْرِينَ وَقَالَ إِنَّمَا الشَّهْرُ تِسْعٌ وَعِشْرُونَ ‏","","",""],[14144,14144,"","আমরা একটি ছেলের সাথে কথা বলেছি, যে ফাদার আল-জাবিকে নিয়ে একটা প্রশ্ন করেছিল যখন সে আমাকে স্পর্শ করবে। ঈশ্বর আমাকে বলতে হবে, না আমি শুধু ঘুমাবো আর তারপর তুমি আবার তা করবে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏مَتَى كَانَ يَرْمِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَمَّا أَوَّلَ يَوْمٍ فَضُحًى وَأَمَّا بَعْدَ ذَلِكَ فَعِنْدَ زَوَالِ الشَّمْسِ ‏","","",""],[14145,14145,"","আমরা একটা ছেলের কথা বলেছি যে আমাদের সাথে কথা বলেছে, যদি আমি তোমাকে ভালবাসি, কথা দিচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَعْجَبَتْ أَحَدَكُمْ الْمَرْأَةُ فَلْيَعْمِدْ إِلَى امْرَأَتِهِ فَلْيُوَاقِعْهَا فَإِنَّ ذَلِكَ يَرُدُّ مِنْ نَفْسِهِ ‏","","",""],[14146,14146,"","আমরা কথা বলেছি একটি ছেলে নিয়ে কথা বলেছি যে আমি কী বলব. তাকে ঈশ্বরের কাছে প্রার্থনা করতে বাধ্য করা হয়েছিল তার এটা করতে হবে তার এটা করা উচিত আর তাকে বিশ্বাস করা উচিত নয়.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ شَأْنِ ‏ ‏ثَقِيفٍ ‏ ‏إِذْ بَايَعَتْ فَقَالَ اشْتَرَطَتْ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ لَا ‏ ‏صَدَقَةَ ‏ ‏عَلَيْهَا وَلَا جِهَادَ ‏","","",""],[14147,14147,"","আমরা ভালো কথা বলেছি, আমরা একটি ছেলের সাথে কথা বলেছি, সে বিশ্বাস করবে যে তারা আমাকে হাইভ দেবে কিনা।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ وَأَخْبَرَنِي ‏ ‏جَابِرٌ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَيَصَّدَّقُونَ وَيُجَاهِدُونَ إِذَا أَسْلَمُوا ‏ ‏يَعْنِي ‏ ‏ثَقِيفًا ‏","","",""],[14148,14148,"","আমরা কথা বলেছি তার বাবার সাথে কথা বলেছি, সে চলে যাওয়ার পর সে একটা কম্পনের কথা বলবে.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ فِي غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏بَعْدَ أَنْ رَجَعْنَا ‏ ‏إِنَّ ‏ ‏بِالْمَدِينَةِ ‏ ‏لَأَقْوَامًا مَا سِرْتُمْ مَسِيرًا وَلَا هَبَطْتُمْ وَادِيًا إِلَّا وَهُمْ مَعَكُمْ حَبَسَهُمْ الْمَرَضُ ‏","","",""],[14149,14149,"","আমরা এমন এক ছেলের সঙ্গে কথা বলেছিলাম, যিনি আমাদের সঙ্গে কথা বলেছিলেন যে তারা কীভাবে প্রতারণা করেছে । শহর তাকে ভণ্ডের অনেক কাজ করতে দিয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُمْ غَزَوْا غَزْوَةً فِيمَا بَيْنَ ‏ ‏مَكَّةَ ‏ ‏وَالْمَدِينَةِ ‏ ‏فَهَاجَتْ ‏ ‏عَلَيْهِمْ رِيحٌ شَدِيدَةٌ حَتَّى دَفَعَتْ الرِّجَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا لِمَوْتِ ‏ ‏الْمُنَافِقِ ‏ ‏فَرَجَعْنَا إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَوَجَدْنَاهُ ‏ ‏مُنَافِقًا ‏ ‏عَظِيمَ النِّفَاقِ قَدْ مَاتَ ‏","","",""],[14150,14150,"","আমরা কথা বলেছি আমাদের বাবার সাথে কথা বলার জন্য। আমরা কথা বলেছি, তিনি বললেন, তিনি ঈশ্বরের কাছে প্রার্থনা করছেন। তিনি ঈশ্বরের কাছে প্রার্থনা করছেন, তিনি তাঁর কাছে প্রার্থনা করছেন এবং তাঁর প্রভুর কাছে তার আচরণ তুলে ধরবে। এবং আমি যাব এবং আমি যাব এবং আমি তার সাথে কথা বলব। এবং আমি আমার বাবার সাথে কথা বলি, আমি আমার বাবার সাথে কথা বলি। এবং আমি আমার বাবার সাথে কথা বলি, আমি আমার বাবার সাথে কথা বলি। এবং আমি আমার ছেলের সাথে কথা বলি, আমি যদি তুমি আমাকে বলতে দাও, আমি তোমার কাছে, আমি তোমার সাথে কথা বলি, আমি তোমার সাথে আমার বাবার সাথে কথা বলি, ছাড়","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ ‏ ‏الْعَقَبَةِ ‏ ‏فَقَالَ شَهِدَهَا سَبْعُونَ فَوَافَقَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَبَّاسُ بْنُ عَبْدِ الْمُطَّلِبِ ‏ ‏آخِذٌ بِيَدِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَذْتُ وَأَعْطَيْتُ ‏","","",""],[14151,14151,"","আমরা সবাই একটা ছেলের কথা বলেছি যে আমাদের সাথে ঈশ্বরের দোহাইের কথা বলেছে, সে তার ঋণের উপত্যকায় একজন যাত্রী নিয়ে যাচ্ছে না আর সে বলেছে সে এক সময় এই অবস্থায় ছিল।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيَسِيرَنَّ رَاكِبٌ فِي جَنْبِ وَادِي ‏ ‏الْمَدِينَةِ ‏ ‏لَيَقُولَنَّ لَقَدْ كَانَ فِي هَذِهِ مَرَّةً حَاضِرَةٌ مِنْ الْمُؤْمِنِينَ كَثِيرٌ ‏","","",""],[14152,14152,"","আমরা ভালো করেই কথা বলেছি, আমরা একটি ছেলের সাথে কথা বলেছি, সে বলবে সে এটা খেতে দেবে না এবং দুনিয়াকে জিজ্ঞেস করে দেবে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏جَابِرٌ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيَتْرُكَنَّهَا أَهْلُهَا مُرْطِبَةً قَالُوا فَمَنْ يَأْكُلُهَا يَا رَسُولَ اللَّهِ قَالَ عَافِيَةُ الطَّيْرِ وَالسِّبَاعِ ‏","","",""],[14153,14153,"","আমরা সবাই একটা ছেলের কথা বলেছি বাবা আল জাবেরের ব্যাপারে আমি যাবে যাবে যাবে যাবে যাবে জাতারেরেরের কথা যে ঈশ্বর ভুলে গেছে তার কাছে, কিন্তু তখন মানুষ পড়ে যাবে বাকি সবাই তাদের সাথে বেইতনে নিয়ে যাবে আর তাদের জন্য ভাল শহরেও তাদের জন্য.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَخْبَرَنِي ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيَأْتِيَنَّ عَلَى ‏ ‏الْمَدِينَةِ ‏ ‏زَمَانٌ يَنْطَلِقُ النَّاسُ فِيهَا إِلَى الْآفَاقِ يَلْتَمِسُونَ الرَّخَاءَ فَيَجِدُونَ رَخَاءً ثُمَّ يَأْتُونَ فَيَتَحَمَّلُونَ بِأَهْلِيهِمْ إِلَى الرَّخَاءِ ‏ ‏وَالْمَدِينَةُ ‏ ‏خَيْرٌ لَهُمْ لَوْ كَانُوا يَعْلَمُونَ ‏","","",""],[14154,14154,"","আমরা কথা বলেছি একটি ছেলে নিয়ে আমরা কথা বলেছি, আমি ঐ লোকের দৃষ্টি বলে দেব যে কিনা এই ভুয় এর একটা অংশে বিশ্বাস করে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَخْبَرَنِي ‏ ‏جَابِرٌ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏رُؤْيَا الرَّجُلِ الْمُؤْمِنِ جُزْءٌ مِنْ النُّبُوَّةِ ‏","","",""],[14155,14155,"","আমরা কথা বলেছি একটি ছেলে নিয়ে কথা বলেছি যে আমরা কি করে ভালো বাবাকে ফোন করেছি যে আমি উত্তর পাব। ঈশ্বর তার জন্য প্রার্থনা করেছেন, আর আমি তার কাছে যাব না, আমি তার জন্য প্রার্থনা করছি, আর আমি কোন শার্ট পরবো না। আর জিততে পারবে না।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ ‏ ‏مِيثَرَةِ ‏ ‏الْأُرْجُوَانِ ‏ ‏فَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا أَرْكَبُهَا وَلَا أَلْبَسُ قَمِيصًا مَكْفُوفًا بِحَرِيرٍ وَلَا أَلْبَسُ ‏ ‏الْقَسِّيَّ ‏","","",""],[14156,14156,"","আমরা একটি ছেলে কথা বলেছি যে ভালো বাবার সাথে কথা বলেছি... ...আমি মৃত্যুর জন্য উত্তর চাই. আর আমরা স্টোনের কাছে যা খুঁজছি তার জন্য আত্মসমর্পণ করছি, দ্যা ফ্ল্যাট এর ভেতরে আছে, তুমি পারবে না।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الْفَأْرَةِ تَمُوتُ فِي الطَّعَامِ أَوْ الشَّرَابِ أَطْعَمُهُ قَالَ لَا ‏ ‏زَجَرَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ كُنَّا نَضَعُ السَّمْنَ فِي الْجِرَارِ فَقَالَ إِذَا مَاتَتْ الْفَأْرَةُ فِيهِ فَلَا تَطْعَمُوهُ ‏","","",""],[14157,14157,"","আমরা ভালো করেই বলেছি বাবা আল-জাওর সাথে কথা বলে আমাদের বিভ্রান্ত করার জন্য। ঈশ্বর তাকে আদেশ দিয়েছেন, যেন সে ব্যর্থ না হয়। সে তাকে গুলি করে এবং ঈশ্বর এটা করতে না পারে। সে সবার সামনে যেতে চেয়েছিল আর চলে যেতে হয়েছিল.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الضَّبِّ فَقَالَ أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِهِ فَقَالَ لَا أَطْعَمُهُ وَقَذِرَهُ ‏ ‏فَقَالَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يُحَرِّمْهُ وَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَيَنْفَعُ بِهِ غَيْرَ وَاحِدٍ وَهُوَ طَعَامُ عَامَّةِ الرِّعَاءِ وَلَوْ كَانَ عِنْدِي لَطَعِمْتُهُ ‏","","",""],[14158,14158,"","আমরা সবাই একটা ছেলের কথা বলেছি যে আমাদের সাথে কথা বলেছে, সে বলেছিল কেউ তার ভাইয়ের বিচার করবে না... ভাগ্য হারিয়ে যাবে.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُقِيمُ أَحَدُكُمْ أَخَاهُ يَوْمَ الْجُمُعَةِ ثُمَّ يُخَالِفُهُ إِلَى مَقْعَدِهِ فَيَقْعُدُ فِيهِ وَلَكِنْ لِيَقُولَنَّ تَفَسَّحُوا ‏","","",""],[14159,14159,"","আমরা একটি ছেলে কথা বলেছি ভাল কথা বলে আমাদের বিভ্রান্ত করার জন্য একটি ছেলে আমাদের সাথে কথা বলেছে যে আমি একজন প্রতিবেশীকে জিজ্ঞেস করব যে বিয়ে হবে কিনা। যদি সে তার সব বই বলে, ঈশ্বর তার জন্য প্রার্থনা করে এরপর তার বই জমা দেন ।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏عَنْ الرَّجُلِ ‏ ‏يَتَوَلَّى ‏ ‏مَوْلَى ‏ ‏الرَّجُلِ بِغَيْرِ إِذْنِهِ فَقَالَ كَتَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى كُلِّ بَطْنٍ عُقُولَهُمْ ثُمَّ كَتَبَ إِنَّهُ لَا يَحِلُّ أَنْ ‏ ‏يُتَوَلَّى ‏ ‏مَوْلَى ‏ ‏رَجُلٍ مُسْلِمٍ بِغَيْرِ إِذْنِهِ ‏","","",""],[14160,14160,"","আমরা সবাই একটা ছেলের কথা বলেছি যে আমাদের সাথে ঈশ্বরের দোহাইের কথা বলেছে, সে তোমার সব পেপারে অভিশপ্ত হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ فِي صَحِيفَتِهِ مَنْ فَعَلَ ذَلِكَ ‏","","",""],[14161,14161,"","আমরা একটা ছেলের কথা বলেছিলাম, আমরা একজন ভালো বাবা হওয়ার কথা বলেছিলাম, কে না একজনকে বলতে পারবে যে একটা ওষুধ খাওয়াটা একটা বিষ্ময়কর.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَرَكَ دِينَارًا فَهُوَ كَيَّةٌ ‏","","",""],[14162,14162,"","আমরা একটা ছেলের কথা বলেছি, যে প্রভুর বাবা-মার সাথে কথা বলেছে, সে বলল সে প্রার্থনা করার আদেশ দিয়েছে, দরজা খুলে বলবে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏ثُوِّبَ ‏ ‏بِالصَّلَاةِ فُتِحَتْ أَبْوَابُ السَّمَاءِ وَاسْتُجِيبَ الدُّعَاءُ ‏","","",""],[14163,14163,"","আমরা একটা ছেলের কথা বলেছিলাম, আমরা একজন ভালো বাবার সাথে কথা বলেছিলাম। সে সূর্যকে তুলে নিয়েছে আর সে দেখেছে সূর্যটা ভালো আর ভালো বলেছে। সে এটা করেছে, ঈশ্বরের কাছে যা করেছে, আমরা তা করেছি। পরের বার আমাদের শহরে ঋণ প্রদান এবং আশীর্বাদ করার জন্য কিছু সময় আসবে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا وَنَظَرَ إِلَى ‏ ‏الشَّامِ ‏ ‏فَقَالَ اللَّهُمَّ أَقْبِلْ بِقُلُوبِهِمْ وَنَظَرَ إِلَى ‏ ‏الْعِرَاقِ ‏ ‏فَقَالَ نَحْوَ ذَلِكَ وَنَظَرَ قِبَلَ كُلِّ ‏ ‏أُفُقٍ ‏ ‏فَفَعَلَ ذَلِكَ وَقَالَ ‏ ‏اللَّهُمَّ ارْزُقْنَا مِنْ ثَمَرَاتِ الْأَرْضِ وَبَارِكْ لَنَا فِي مُدِّنَا وَصَاعِنَا ‏","","",""],[14164,14164,"","আমরা কথা বলেছি একটা ছেলে তার বাবার সাথে কথা বলবে.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏طَيْرُ كُلِّ عَبْدٍ فِي عُنُقِهِ ‏","","",""],[14165,14165,"","আমরা একটি ছেলের কথা বলেছি, আমরা তার বাবার সাথে এরকম কিছু করার কথা বলেছি। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমি তাকে তার সাথে একমত হতে বলবো যে তিনি এই বিষয়ে একমত। তার মৃত্যুর সাথে তার কোন সম্পর্ক নেই, তারপর সে তার অনুমতি পায় নি। আর বলেন যে আমার ছেলে আমাকে কখনো যেতে দেয় নি। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং আমাদের যা করতে হবে তা যেন না বলি,","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ أَزْوَاجَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَأَلْنَهُ النَّفَقَةَ فَلَمْ يُوَافِقْ عِنْدَهُ شَيْءٌ حَتَّى أَحْجَزْنَهُ فَأَتَاهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَاسْتَأْذَنَ عَلَيْهِ فَلَمْ يُؤْذَنْ لَهُ ثُمَّ أَتَاهُ ‏ ‏عُمَرُ ‏ ‏فَاسْتَأْذَنَ عَلَيْهِ فَلَمْ يُؤْذَنْ لَهُ ثُمَّ اسْتَأْذَنَا بَعْدَ ذَلِكَ فَأُذِنَ لَهُمَا وَوَجَدَاهُ بَيْنَهُنَّ فَقَالَ لَهُ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ ‏ ‏ابْنَةَ زَيْدٍ ‏ ‏سَأَلَتْنِي النَّفَقَةَ ‏ ‏فَوَجَأْتُهَا ‏ ‏أَوْ نَحْوَ ذَلِكَ ‏ ‏وَأَرَادَ بِذَلِكَ أَنْ يُضْحِكَهُ فَضَحِكَ حَتَّى بَدَتْ ‏ ‏نَوَاجِذُهُ ‏ ‏وَقَالَ وَالَّذِي نَفْسِي بِيَدِهِ مَا حَبَسَنِي غَيْرُ ذَلِكَ فَقَامَا إِلَى ابْنَتَيْهِمَا فَأَخَذَا بِأَيْدِيهِمَا فَقَالَا أَتَسْأَلَانِ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا لَيْسَ عِنْدَهُ فَنَهَاهُمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْهُمَا فَقَالَا لَا نَعُدْ فَعِنْدَ ذَلِكَ نَزَلَ ‏ ‏التَّخْيِيرُ ‏","","",""],[14166,14166,"","আমরা দুজন ভাইয়ের সাথে ঘুমের সময় গিয়েছিলাম, যারা আমার ভাইয়ের সাথে কথা বলেছে, কিন্তু ঈশ্বরের কাছে বাবার ছেলের জন্য ভালো আছে। তার তিনটি মূল্য রয়েছে, এটা যুদ্ধ-শর্ত রক্ত আর একটা গণ ব্যবস্থা যেটা অগ্নি নির্বাপক যুদ্ধার আর আদালতকে সরিয়ে নেয়া হয়েছে যার ফলে একটি ভালো টাকা দিয়ে তা প্রতিস্থাপন করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَخِي جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَجَالِسُ بِالْأَمَانَةِ إِلَّا ثَلَاثَةَ مَجَالِسَ ‏ ‏مَجْلِسٌ ‏ ‏يُسْفَكُ ‏ ‏فِيهِ دَمٌ حَرَامٌ وَمَجْلِسٌ يُسْتَحَلُّ فِيهِ فَرْجٌ حَرَامٌ وَمَجْلِسٌ يُسْتَحَلُّ فِيهِ مَالٌ مِنْ غَيْرِ حَقٍّ ‏","","",""],[14167,14167,"","আমরা ভাল করেছি, আমি বলতে চাচ্ছি যে, আমার প্রভু ঈশ্বরের পুত্র... ...আমার গৌরবের জন্য, আমি আমার গৌরবের জন্য প্রার্থনা করা উচিত. মায়া হল তার ।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏وَعَبْدُ الْجَبَّارِ بْنُ مُحَمَّدٍ الْخَطَّابِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ يَعْنِي ابْنَ عَمْرٍو الرَّقِّيَّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏هَذَا أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ إِلَّا ‏ ‏الْمَسْجِدَ الْحَرَامَ ‏ ‏وَصَلَاةٌ فِي ‏ ‏الْمَسْجِدِ الْحَرَامِ ‏ ‏أَفْضَلُ مِنْ مِائَةِ أَلْفِ صَلَاةٍ ‏ ‏قَالَ ‏ ‏حُسَيْنٌ ‏ ‏فِيمَا سِوَاهُ ‏","","",""],[14168,14168,"","আমরা ঈশ্বরের প্রতি ভালবাসা নিয়ে কথা বলেছি যখন তিনি ঈশ্বরের সাথে যুদ্ধ করতে বলেছিলেন, যখন তুমি তার জন্য প্রার্থনা করেছিলে, সে আমাদের এক এবং পরবর্তী সময়ে ফোন করতো।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِجَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏صَلِّ بِنَا كَمَا رَأَيْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي ‏ ‏فَصَلَّى بِنَا فِي ثَوْبٍ وَاحِدٍ وَشَدَّهُ تَحْتَ ‏ ‏الثَّنْدُوَتَيْنِ ‏","","",""],[14169,14169,"","আমরা এমন একজনকে লড়াই করতে চেষ্টা করেছি যে আমাকে ছেড়ে চলে যাবার চেষ্টা করেছে। ঈশ্বর হঠাৎ করে আমাকে ঈশ্বরের দোহাই পেতে হবে। যে মানুষ ভয়ে ছিল, আমি ভয় পেয়ে গেলাম।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عَمَّارٍ ‏ ‏حَدَّثَنِي ‏ ‏جَارٌ لِجَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَدِمْتُ مِنْ سَفَرٍ فَجَاءَنِي ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏يُسَلِّمُ عَلَيَّ فَجَعَلْتُ أُحَدِّثُهُ عَنْ افْتِرَاقِ النَّاسِ وَمَا أَحْدَثُوا فَجَعَلَ ‏ ‏جَابِرٌ ‏ ‏يَبْكِي ثُمَّ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ النَّاسَ دَخَلُوا فِي دِينِ اللَّهِ أَفْوَاجًا وَسَيَخْرُجُونَ مِنْهُ أَفْوَاجًا ‏","","",""],[14170,14170,"","আমরা কয়েক দিন কথা বলেছি, আমরা ফিরে যাওয়ার পর আমরা কিছু চিন্তা করেছি। ভাল প্রভু বলেছে আমি তার জন্য ঈশ্বরের কাছে চেষ্টা করছি এবং তাকে যেতে বলে। খারাপভাবে, সে আছে। আমি কি? আমি এটা করতে চাই। আমি কি মনে করি, আমি কি করেছি? আমি এটা ঠিক আছে? আমি কি জানি না যে, আমি এটা করতে পারি? আমি এটা ঠিক আছে? আমি কি করেছি? আমি এটা ঠিক করেছি, আমি এটা ঠিক করেছি, আমি এটা ঠিক করেছি, আমি এটা করতে পারি। আমি যদি আমার জন্য একটি ছোট দল হিসেবে কাজ করি, আমি এটা করতে পারি। আমি কি করছি। আমি এটা করতে চাই। আমি কি করছি। আমি কি করছি? আমি এটা করতে পারি? আমি কি করবো? আমি এটা করতে চাই না যে, আমি এটা করতে পারি? আমি কি করবো? পানি থেকে যা ঈশ্বরের মুখ মুখ বন্ধ রাখবে... ...আর সে হাত ধরে আছে, চোখটা ঈশ্বরের কাছে প্রার্থনা করা ঈশ্বরের কাছে প্রার্থনা করা থেকে বিক্রয় করছে। এটা রেখে দাও আর এটা পৌছে দাও।","‏ ‏حَدَّثَنَا ‏ ‏سَيَّارُ بْنُ حَاتِمٍ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرٌ يَعْنِي ابْنَ سُلَيْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏الْجَعْدُ أَبُو عُثْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏اشْتَكَى ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيْهِ الْعَطَشَ قَالَ ‏ ‏فَدَعَا ‏ ‏بِعُسٍّ ‏ ‏فَصُبَّ فِيهِ شَيْءٌ مِنْ مَاءٍ فَوَضَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِ يَدَهُ وَقَالَ اسْقُوا فَاسْتَقَى النَّاسُ قَالَ فَكُنْتُ أَرَى الْعُيُونَ تَنْبُعُ مِنْ بَيْنِ أَصَابِعِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[14171,14171,"","আমরা সবাই এক নিশ্চিত, একজন মূসা এর ছেলে, যে একজন ফ্রিল্যান্সারকে দান করেছে, ঈশ্বরের অনুগ্রহে...","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَاشِدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كُنَّا نُصِيبُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَغَانِمِنَا مِنْ الْمُشْرِكِينَ ‏ ‏الْأَسْقِيَةَ ‏ ‏وَالْأَوْعِيَةَ فَنَقْسِمُهَا وَكُلُّهَا مَيْتَةٌ ‏","","",""],[14172,14172,"","আমরা একজন মাতালের সাথে কথা বলেছিলাম যে আমাদের সাথে কথা বলতে চেয়েছিল, ঈশ্বরের বাজে কথা ছিল, আর সে আমাদের সাথে সাঁতার কাটতে দিত,","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نَتَمَسَّحَ بِعَظْمٍ أَوْ ‏ ‏بَعْرٍ ‏","","",""],[14173,14173,"","আমরা মূসা-এর সাথে কথা বলেছি, যখন আমরা একটি ছেলে খুঁজে বের করতে পারি যে হয়ত হয়ত এই পথ দিয়ে গেছে। ঈশ্বর তাকে উদ্ধার করতে হবে এবং তার হৃদয়ের মানুষটিকে ঈশ্বরের একজন মানুষের কাছে পাঠিয়ে দেবে। আজ রাতে আমরা কোন পানি পাইনি... ...আর আমাদের কাছে এমন কোন পানি ছিল না যেটা হার্ট এটা দিয়ে সে তোমার বন্ধুদের সাথে বন্ধুত্ব করতে পারবে.","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ وَرَجُلٌ مِنْ أَصْحَابِهِ عَلَى رَجُلٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فِي ‏ ‏حَائِطٍ ‏ ‏وَهُوَ يُحَوِّلُ الْمَاءَ فَقَالَ عِنْدَكَ مَاءٌ بَاتَ اللَّيْلَةَ فِي ‏ ‏شَنٍّ ‏ ‏وَإِلَّا ‏ ‏كَرَعْنَا ‏ ‏فَقَالَ عِنْدِي مَاءٌ بَائِتٌ فَانْطَلَقَ إِلَى ‏ ‏عَرِيشٍ ‏ ‏فَحَلَبَ لَهُ شَاةً ثُمَّ ‏ ‏صَبَّ عَلَيْهِ مَاءً بَائِتًا ثُمَّ سَقَاهُ وَصَنَعَ بِصَاحِبِهِ مِثْلَ ذَلِكَ ‏","","",""],[14174,14174,"","আমরা ঈশ্বরের জামাতায় বাপ্তাইজিত হয়েছি এবং সে আমার শ্বশুরের সাথে জন্ম নিয়েছে, কিন্তু ঈশ্বর শুনেছেন যে সে কতটা ঔষধে আছে। অথবা গোপন পাপ, আমি থাকছি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ وَهُوَ أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الرَّحْمَنِ يَعْنِي ابْنَ الْغَسِيلِ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنْ كَانَ ‏ ‏أَوْ إِنْ يَكُنْ ‏ ‏فِي شَيْءٍ مِنْ أَدْوِيَتِكُمْ خَيْرٌ فَفِي شَرْطَةِ ‏ ‏مِحْجَمٍ ‏ ‏أَوْ شَرْبَةِ عَسَلٍ أَوْ ‏ ‏لَذْعَةٍ ‏ ‏بِنَارٍ تُوَافِقُ دَاءً وَمَا أُحِبُّ أَنْ أَكْتَوِيَ ‏","","",""],[14175,14175,"","আমরা সকালেই বাপ্তিস্ম নিয়েছি, আমরা ঈশ্বরের পর্দার উপর আমার বিষ প্রয়োগের ব্যাপারে কথা বলেছি। আমি শুনেছি, আমি সকাল থেকে এসেছি, আর সে তার মতো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الصَّبَّاحِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ زَكَرِيَّا ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَابِطٍ ‏ ‏وَأَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ اهْدِ ‏ ‏ثَقِيفًا ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏مُحَمَّدِ بْنِ الصَّبَّاحِ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[14176,14176,"","আমি আমার ভয়কে খুঁজে পেয়েছি, ঈশ্বর তাকে আশীর্বাদ করেছেন আর জিজ্ঞেস করেছেন আমি কি মনে করি।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏أَخْبَرَنِي ‏ ‏دَاوُدُ بْنُ بَكْرِ بْنِ أَبِي الْفُرَاتِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا أَسْكَرَ كَثِيرُهُ فَقَلِيلُهُ حَرَامٌ ‏","","",""],[14177,14177,"","আমরা কথা বলার চেয়ে ভাল এক শট নিয়ে কথা বলেছি। একজন যুবককে খুন করা... ...যে বলেছিল আমরা লর্ডের বার্তাবাহকের সাথে বাইরে গিয়েছিলাম, একজন মহিলা ধরা পড়েছিলো, তো, তাই... হঠাৎ করেই চলে গেল, এটা শেষ হবে না... ...আর সে যেতে দেবে. যে মানুষ মারা গেছে সে মারা গেছে, তার জন্য ঐ দুই ভাঁড়ের দল তার কাছ থেকে বের হয়ে আসছে যারা বলেছিল আমরা জিতবো. আমি তাকে বলছি, অথবা অন্য কেউ আমাকে যুদ্ধে যেতে বলার জন্য যথেষ্ট অর্থ দিতে হবে যখন আমার ককপিট পথে চলে যাবে। সে জানতো সে হল, সে হল দাড়িয়ে থাকা শ্রেষ্ঠ, তিনি এটা তার অবস্থানে রেখেছিলেন এবং তারপর তার হৃদয় ফিরে পান যেন তিনি তার জায়গায় খুঁজে পান এবং তারপর তিনি তার জায়গায় চলে যান তার রুমে ফিরে, সে প্রমাণ করলো যে মানুষ যখন তাদের দেখেছে, সে জানতো আমরা হয়ত তার সাথে বাইরে বের হব, সে পালিয়ে পালিয়ে পালিয়ে পালিয়ে পালিয়ে যেতো। ঈশ্বর বলেছিলেন আমি আমার বিছানায় ছিলাম না। এটা পড়, আমি এটা করতে পছন্দ করি যতক্ষণ না আমি এটা করি, আমি আমার আদেশটা আরও বেশি রাখব, আমি তার জন্য ঈশ্বরের কাছে যাবো এবং তার সংক্ষিপ্ত সংক্ষিপ্ত কিছু সরবরাহ করবো।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏قِرَاءَةً ‏ ‏حَدَّثَنِي ‏ ‏صَدَقَةُ بْنُ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَقِيلِ بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةِ ‏ ‏ذَاتِ الرِّقَاعِ ‏ ‏فَأُصِيبَتْ امْرَأَةٌ مِنْ الْمُشْرِكِينَ فَلَمَّا انْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَافِلًا ‏ ‏وَجَاءَ زَوْجُهَا وَكَانَ غَائِبًا فَحَلَفَ أَنْ لَا يَنْتَهِيَ حَتَّى ‏ ‏يُهْرِيقَ ‏ ‏دَمًا فِي ‏ ‏أَصْحَابِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَرَجَ يَتْبَعُ ‏ ‏أَثَرَ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَزَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْزِلًا فَقَالَ مَنْ رَجُلٌ ‏ ‏يَكْلَؤُنَا ‏ ‏لَيْلَتَنَا هَذِهِ ‏ ‏فَانْتَدَبَ ‏ ‏رَجُلٌ مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏وَرَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَا نَحْنُ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏فَكُونُوا ‏ ‏بِفَمِ ‏ ‏الشِّعْبِ ‏ ‏قَالَ وَكَانُوا نَزَلُوا إِلَى ‏ ‏شِعْبٍ ‏ ‏مِنْ ‏ ‏الْوَادِي ‏ ‏فَلَمَّا خَرَجَ الرَّجُلَانِ إِلَى ‏ ‏فَمِ ‏ ‏الشِّعْبِ ‏ ‏قَالَ الْأَنْصَارِيُّ ‏ ‏لِلْمُهَاجِرِيِّ أَيُّ اللَّيْلِ أَحَبُّ إِلَيْكَ أَنْ ‏ ‏أَكْفِيَكَهُ ‏ ‏أَوَّلَهُ أَوْ آخِرَهُ قَالَ ‏ ‏اكْفِنِي ‏ ‏أَوَّلَهُ فَاضْطَجَعَ ‏ ‏الْمُهَاجِرِيُّ فَنَامَ وَقَامَ الْأَنْصَارِيُّ ‏ ‏يُصَلِّي وَأَتَى الرَّجُلُ فَلَمَّا رَأَى شَخْصَ الرَّجُلِ عَرَفَ أَنَّهُ ‏ ‏رَبِيئَةُ ‏ ‏الْقَوْمِ فَرَمَاهُ بِسَهْمٍ فَوَضَعَهُ فِيهِ فَنَزَعَهُ فَوَضَعَهُ وَثَبَتَ قَائِمًا ثُمَّ رَمَاهُ بِسَهْمٍ آخَرَ فَوَضَعَهُ فِيهِ فَنَزَعَهُ فَوَضَعَهُ وَثَبَتَ قَائِمًا ثُمَّ عَادَ لَهُ بِثَالِثٍ فَوَضَعَهُ فِيهِ فَنَزَعَهُ فَوَضَعَهُ ثُمَّ رَكَعَ وَسَجَدَ ثُمَّ ‏ ‏أَهَبَّ ‏ ‏صَاحِبَهُ فَقَالَ اجْلِسْ فَقَدْ أُوتِيتَ ‏ ‏فَوَثَبَ ‏ ‏فَلَمَّا رَآهُمَا الرَّجُلُ عَرَفَ أَنْ قَدْ ‏ ‏نَذَرُوا ‏ ‏بِهِ فَهَرَبَ فَلَمَّا رَأَى ‏ ‏الْمُهَاجِرِيُّ مَا بِالْأَنْصَارِيِّ مِنْ الدِّمَاءِ قَالَ سُبْحَانَ اللَّهِ أَلَا ‏ ‏أَهْبَبْتَنِي ‏ ‏قَالَ كُنْتُ فِي سُورَةٍ أَقْرَؤُهَا فَلَمْ أُحِبَّ أَنْ أَقْطَعَهَا حَتَّى أُنْفِذَهَا فَلَمَّا تَابَعَ الرَّمْيَ رَكَعْتُ فَأُرِيتُكَ وَايْمُ اللَّهِ لَوْلَا أَنْ أُضَيِّعَ ‏ ‏ثَغْرًا ‏ ‏أَمَرَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِحِفْظِهِ لَقَطَعَ نَفْسِي قَبْلَ أَنْ أَقْطَعَهَا أَوْ أُنْفِذَهَا ‏","","",""],[14178,14178,"","আমরা আমার বাবার কথা বলেছি যে তোমার বাবার টাকা আমার বাবার কাছে, সে তার মুখের সব মানুষদের ছেড়ে দেবে অথবা একভাবে হাঁটবে। তার বধিরদের গন্ধের কথা বলছি।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يَأْكُلَ الرَّجُلُ بِشِمَالِهِ أَوْ يَمْشِيَ فِي نَعْلٍ وَاحِدَةٍ وَأَنْ ‏ ‏يَشْتَمِلَ ‏ ‏الصَّمَّاءَ ‏ ‏وَأَنْ ‏ ‏يَحْتَبِيَ ‏ ‏فِي ثَوْبٍ وَاحِدٍ كَاشِفًا عَنْ فَرْجِهِ ‏","","",""],[14179,14179,"","আমরা আমার বাবা আর একজন রক্ষকের খোঁজ করেছি... ...যার হৃদয় বহন করার জন্য আহ্বান জানানো হয়েছে. একটা জিনিস বের করো, সে তার সিট থেকে বের হয়ে এসেছে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏هَاشِمِ بْنِ هَاشِمِ بْنِ عُتْبَةَ بْنِ أَبِي وَقَّاصٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ نِسْطَاسٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَحْلِفُ أَحَدٌ عَلَى مِنْبَرِي كَاذِبًا إِلَّا تَبَوَّأَ مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[14180,14180,"","আমরা আমার নিজের মিষ্টি মুছে ফেলার চেষ্টা করেছি এবং বাবা খুশি মানে আমার ছেলে খুবই দুঃখের স্বপ্ন দেখে আর তাই সে জেগে আছে। আমার বাবা, আমরা যে টাকা তৈরি করেছি, তা নিশ্চয়ই হতে হবে। আমরা জানতে পারব কিভাবে পবিত্র পিতার কাছ থেকে শিখতে হয়। তারপর ফ্লাইট তাদের বলবে, আমি তোমাদের পতাকায় নির্বাচিত করবো এবং তোমাদের ভাগ্য তোমাদের জন্য নির্ধারণ করা হবে। তুমি জানো, আমি জানি না তুমি সেই রহস্য শিক্ষক যে এটা ভালোর জন্য শিক্ষা দিচ্ছে কিনা। সুখী জীবিত থাকা এবং আমার উপর নজর রাখ আর তারপর আমার উপর আপনার আশীর্বাদ নিয়ে আসে। আমি এখন যাচ্ছি। আমাকে এটা সম্পর্কে বলতে হবে এবং আমি খুশি হতে চাই আমার আশীর্বাদ আছে, আর তুমি আমার জন্য এটা জান ডেনি আর আমার জীবন আমার জন্য ভাল। আমার বাবা বলেছিলেন যে তিনি এখানে এসেছেন। আমার হৃদয়ের মধ্যে সে হয়তো তাকে আমার বাবার দিকে তাকিয়েছে, ঈশ্বরের অবিশ্বস্ত ছেলের কথা আর আমাদের শান্তি নিয়ে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏وَأَبُو سَعِيدٍ ‏ ‏يَعْنِي مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏الْمَعْنَى وَهَذَا لَفْظُ ‏ ‏إِسْحَاقَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الْمَوَالِ الْمَدَنِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعَلِّمُنَا ‏ ‏الِاسْتِخَارَةَ كَمَا يُعَلِّمُنَا السُّورَةَ مِنْ الْقُرْآنِ يَقُولُ ‏ ‏إِذَا هَمَّ أَحَدُكُمْ بِالْأَمْرِ فَلْيَرْكَعْ رَكْعَتَيْنِ مِنْ غَيْرِ الْفَرِيضَةِ ثُمَّ لِيَقُلْ اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ وَتَعْلَمُ وَلَا أَعْلَمُ وَأَنْتَ عَلَّامُ الْغُيُوبِ اللَّهُمَّ فَإِنْ كُنْتَ تَعْلَمُ هَذَا الْأَمْرَ يُسَمِّيهِ بِاسْمِهِ خَيْرًا لِي فِي دِينِي وَمَعَاشِي ‏ ‏قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏وَمَعِيشَتِي ‏ ‏وَعَاقِبَةِ أَمْرِي فَاقْدُرْهُ لِي وَيَسِّرْهُ ثُمَّ بَارِكْ لِي فِيهِ اللَّهُمَّ وَإِنْ كُنْتَ تَعْلَمُهُ شَرًّا لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي فَاصْرِفْنِي عَنْهُ وَاصْرِفْهُ عَنِّي وَاقْدُرْ لِي الْخَيْرَ حَيْثُ كَانَ ثُمَّ رَضِّنِي بِهِ ‏ ‏وَقَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏وَعَاقِبَةِ أَمْرِي فَاقْدُرْهُ لِي وَيَسِّرْ لِي وَبَارِكْ لِي فِيهِ اللَّهُمَّ وَإِنْ كُنْتَ تَعْلَمُهُ شَرًّا لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي فَاصْرِفْنِي عَنْهُ وَاصْرِفْهُ عَنِّي وَاقْدُرْ لِي الْخَيْرَ حَيْثُ كَانَ ثُمَّ رَضِّنِي بِهِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏حَدَّثَنَاه ‏ ‏مَنْصُورُ بْنُ أَبِي مُزَاحِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الْمَوَالِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏","","",""],[14181,14181,"","আমরা আমার গলা মুছে ফেলতে চেষ্টা করেছি কিন্তু সাগরকে সাহায্য করতে চেয়েছিলাম। আমি ঈশ্বরের কাছে প্রার্থনা করছি, যেন তা ছেড়ে দেন এবং চোখ থেকে তা সরিয়ে নিতে পারি। যদি তারা কোন একটা ঘরে শুরু করতে পারে। বছর হোক বা না হোক, আমরা থামতাম।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنِي ‏ ‏فُلَيْحُ بْنُ سُلَيْمَانَ الْمَدَنِيُّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى قَوْمًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏يَعُودُ ‏ ‏مَرِيضًا فَاسْتَقَاهُمْ ‏ ‏وَجَدْوَلٌ ‏ ‏قَرِيبٌ مِنْهُ فَقَالَ ‏ ‏إِنْ كَانَ عِنْدَهُمْ مَاءٌ قَدْ بَاتَ فِي ‏ ‏شَنٍّ ‏ ‏وَإِلَّا ‏ ‏كَرَعْنَا ‏","","",""],[14182,14182,"","আমরা কথা বলেছি কে কে কে কে কে, যাকে ঈশ্বরের ভালবাসা বহন করতে বাধ্য করা হয়েছে। ঈশ্বরের কাছে প্রার্থনা করবে এবং তার বন্ধু এবং তার সকল জ্ঞান পরিত্যাগ করবে। তোমার ভাইয়ের জ্ঞান তার আত্মার গৌরবের প্রতীক।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏الْمُنْكَدِرُ بْنُ مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ مَعْرُوفٍ ‏ ‏صَدَقَةٌ ‏ ‏وَمِنْ الْمَعْرُوفِ أَنْ ‏ ‏تَلْقَى أَخَاكَ بِوَجْهٍ طَلْقٍ وَأَنْ تُفْرِغَ مِنْ دَلْوِكَ فِي إِنَائِهِ ‏","","",""],[14183,14183,"","আমরা ঈশ্বরের কথা বলেছিলাম, আমি ঈশ্বরের কাছে প্রার্থনা করব, আর সে চুপ থাকবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي أَيُّوبَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ جَابِرٍ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَامَ رَمَضَانَ وَسِتَّةَ أَيَّامٍ مِنْ شَوَّالٍ فَكَأَنَّمَا صَامَ السَّنَةَ كُلَّهَا ‏","","",""],[14184,14184,"","আমরা আপনাদের যুদ্ধ নিয়ে কথা বলেছি, ঈশ্বর আমার উপর দুঃখ প্রকাশ করেছেন। ঈশ্বর লর্ডের হুকুম তুলে ধরেছেন। শুটারের গায়ে আগুন লেগেছে.","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ عَبْدِ اللَّهِ الْمُزَنِيُّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُوجِبَتَانِ مَنْ لَقِيَ اللَّهَ عَزَّ وَجَلَّ وَلَا يُشْرِكُ بِهِ شَيْئًا دَخَلَ الْجَنَّةَ وَمَنْ لَقِيَ اللَّهَ عَزَّ وَجَلَّ وَهُوَ مُشْرِكٌ دَخَلَ النَّارَ ‏","","",""],[14185,14185,"","আমাদের কথা বলা হয়েছে যখন আমরা বিছানায় যেতে চাই, ঈশ্বর বললেন, আল্লাহ তাঁর জন্য প্রার্থনা করেন এবং তিনি বললেন প্রতিটি ধাঁধার আগুন আছে এবং পর্যটকদের মাটিতে থাকার অধিকার আছে।","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِكُلِّ نَبِيٍّ ‏ ‏حَوَارِيًّا ‏ ‏وَإِنَّ ‏ ‏حَوَارِيَّ ‏ ‏الزُّبَيْرُ ‏","","",""],[14186,14186,"","আমরা বেনকে খুঁজছি আমার শ্বশুর আব্বা সম্পর্কে বেনকে খুশি করার জন্য না, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং বন্য মাস ধরে জয় লাভ করবেন, না জয়ের জন্য।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمْ يَكُنْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْزُو فِي الشَّهْرِ الْحَرَامِ إِلَّا أَنْ ‏ ‏يُغْزَى ‏ ‏أَوْ يُغْزَوْا ‏ ‏فَإِذَا حَضَرَهُ أَقَامَ حَتَّى ‏ ‏يَنْسَلِخَ ‏","","",""],[14187,14187,"","আমরা কথা বলেছি, কিন্তু সে আমাদের সুন্দর চোখওয়ালা ছেলেটির ব্যাপারে কথা বলেছে। আমরা তার বাবার সাথে কথা বলেছি যে সে যে ভালো প্রতিবেশী, তার কথা শোনা উচিত। ঈশ্বরের আছে এবং আমি সে আছে। তাকে এটা তার ঈশ্বরের কাছে দিতে হবে.","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏وَحَسَنُ بْنُ مُوسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏غِفَارٌ ‏ ‏غَفَرَ اللَّهُ لَهَا ‏ ‏وَأَسْلَمُ ‏ ‏سَالَمَهَا اللَّهُ ‏","","",""],[14188,14188,"","আমরা মূসাকে বলেছিলাম যে আমাদের একটি ছেলে আছে আমার শ্বশুর আব্বা সম্পর্কে শুনতে। সে বলবে অয়াসি, অশুভের আগে শুকনো শুকনো খাবার আর শপথটা ছিল।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏غِلَظُ الْقُلُوبِ ‏ ‏وَالْجَفَاءُ ‏ ‏قِبَلَ الْمَشْرِقِ وَالْإِيمَانُ ‏ ‏وَالسَّكِينَةُ ‏ ‏فِي أَهْلِ ‏ ‏الْحِجَازِ ‏","","",""],[14189,14189,"","আমরা মূসা কথা বলেছি, আমরা এক ছেলের কথা বলেছি, যে আমার বাবার বলা এক ছেলে তার কাছে প্রার্থনা করেছে। লর্ড তার কাছে প্রার্থনা করলেন এবং সে বলবে যেন অন্য লোকদের পরাজিত করা হয় এবং খালি হাতে বের হয়ে যাওয়া হয়। দ্বীপ, একটা মই।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏أَخْبَرَهُ أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَأُخْرِجَنَّ ‏ ‏الْيَهُودَ ‏ ‏وَالنَّصَارَى ‏ ‏مِنْ جَزِيرَةِ ‏ ‏الْعَرَبِ ‏ ‏حَتَّى لَا أَذَرَ فِيهَا إِلَّا مُسْلِمًا ‏","","",""],[14190,14190,"","আমরা মূসাকে কথা বলেছি আমার প্রিয় বাবাকে ঈশ্বরের দোহাই দিয়ে বলতে। আমাকে বলা হয়েছে যে তিনি কয়েক ঘন্টা আগে আমাকে বলতেন যে তিনি আমাকে ১ ঘন্টা অপেক্ষা করতে এবং যখন সে এটা জানতে পারে, দিন আসবে। একশ বছর।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ قَبْلَ أَنْ يَمُوتَ بِشَهْرٍ ‏ ‏تَسْأَلُونِي عَنْ السَّاعَةِ وَإِنَّمَا عِلْمُهَا عِنْدَ اللَّهِ أُقْسِمُ بِاللَّهِ مَا عَلَى الْأَرْضِ نَفْسٌ مَنْفُوسَةٌ الْيَوْمَ يَأْتِي عَلَيْهَا مِائَةُ سَنَةٍ ‏","","",""],[14191,14191,"","আমরা মূসা কথা বলেছি ঈশ্বরের একটি পুত্র বা ছেলে আছে কিনা সে বলবে বেন তাদের ডান দিকে এবং ডানের কাছে মিথ্যাবাদী হিসেবে আছে। আর তারা তাদের মধ্যে সবচেয়ে সাধারণ মানুষ। তারা সবাই বলে, তারা সবাই ঈশ্বরের সন্তান। আমার কিছু সাহস বলে দুই মিথ্যাবাদী।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏بَيْنَ يَدَيْ السَّاعَةِ كَذَّابُونَ مِنْهُمْ صَاحِبُ ‏ ‏الْيَمَامَةِ ‏ ‏وَمِنْهُمْ صَاحِبُ ‏ ‏صَنْعَاءَ ‏ ‏الْعَنَسِيُّ ‏ ‏وَمِنْهُمْ صَاحِبُ ‏ ‏حِمْيَرَ ‏ ‏وَمِنْهُمْ ‏ ‏الدَّجَّالُ ‏ ‏وَهُوَ أَعْظَمُهُمْ فِتْنَةً ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏وَبَعْضُ أَصْحَابِي يَقُولُ قَرِيبٌ مِنْ ثَلَاثِينَ كَذَّابًا ‏","","",""],[14192,14192,"","আমরা মূসা কে বলেছিলাম, আমার সুন্দর বাবার সাথে একটা কুড়ান ছেলে নিয়ে আমরা তোমাকে ঠিক করব যাতে তুমি আমাকে দেখতে না পাও। আর নারী আর অনেক দিন ধরে তার জন্য কোন ব্যবস্থা করতে না পারে।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَنَا ‏ ‏فَرَطُكُمْ ‏ ‏بَيْنَ أَيْدِيكُمْ فَإِذَا لَمْ تَرَوْنِي فَأَنَا عَلَى الْحَوْضِ قَدْرَ مَا بَيْنَ ‏ ‏أَيْلَةَ ‏ ‏إِلَى ‏ ‏مَكَّةَ ‏ ‏وَسَيَأْتِي رِجَالٌ وَنِسَاءٌ بِقِرَبٍ وَآنِيَةٍ فَلَا يَطْعَمُونَ مِنْهُ شَيْئًا ‏","","",""],[14193,14193,"","আমরা মূসা কে বলেছিলাম, আমার প্রিয় বাবার সাথে আমার ভালো ছেলের কথা বলেছি, যে লর্ডের কথা শুনেছিল। সে বলল, তুমি আমার মায়ের সাথে লড়াই করো না, যে কিনা ভালোর জন্য খুন করেছে। সে বলবে তারা আমাদের আদেশ দিচ্ছে এই কথা বলতে যে, তোমার কিছু যুবরাজ আছে যাদের এটা করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي يُقَاتِلُونَ عَلَى الْحَقِّ ظَاهِرِينَ إِلَى يَوْمِ الْقِيَامَةِ قَالَ فَيَنْزِلُ ‏ ‏عِيسَى ابْنُ مَرْيَمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَيَقُولُ أَمِيرُهُمْ تَعَالَ صَلِّ بِنَا فَيَقُولُ لَا إِنَّ بَعْضَكُمْ عَلَى بَعْضٍ أَمِيرٌ لِيُكْرِمَ اللَّهُ هَذِهِ الْأُمَّةَ ‏","","",""],[14194,14194,"","আমরা আমার বাবার বিষয়ে দুটো বেশ্যার সন্তান থাকার কথা বলেছিলাম । অপেক্ষা করুন তারা হয়তো বলবে আমরা তার দিকে তাকিয়ে বলবে যে তারা তাকে ভেঙে ফেলেছে এবং সে আপনাকে সব পরিস্কার করে দিয়েছে। আপনি তাকে ছায়া দিয়ে ধোঁকা দিয়েছেন এবং তার সাথে তার সাথে দেখা করবেন। তারা তাদের ওপর স্বর্গে ঘুমিয়ে থাকার জন্য দোষ দেয় এবং তারপর আপনি সমাধান করেন গুজব ছড়িয়ে পড়ে যে সে চলে গেছে, তার হৃদয় হচ্ছে স্বর্গে পরিণত করা নৈতিক চরিত্র এবং এটাকে নরকে পরিণত করা। ধর্ম আর এটা ঘটতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ ‏ ‏جَابِرًا ‏ ‏عَنْ الْوُرُودِ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ نَحْنُ يَوْمَ الْقِيَامَةِ عَلَى كَوْمٍ فَوْقَ النَّاسِ ‏ ‏فَيُدْعَى بِالْأُمَمِ وَبِأَوْثَانِهَا وَمَا كَانَتْ تَعْبُدُ الْأَوَّلَ فَالْأَوَّلَ ثُمَّ يَأْتِينَا رَبُّنَا عَزَّ وَجَلَّ بَعْدَ ذَلِكَ فَيَقُولُ ‏ ‏مَا تَنْتَظِرُونَ فَيَقُولُونَ نَنْتَظِرُ رَبَّنَا عَزَّ وَجَلَّ فَيَقُولُ أَنَا رَبُّكُمْ فَيَقُولُونَ حَتَّى نَنْظُرَ إِلَيْهِ قَالَ ‏ ‏فَيَتَجَلَّى ‏ ‏لَهُمْ عَزَّ وَجَلَّ وَهُوَ يَضْحَكُ وَيُعْطِي كُلَّ إِنْسَانٍ مِنْهُمْ مُنَافِقٍ وَمُؤْمِنٍ نُورًا ‏ ‏وَتَغْشَاهُ ظُلْمَةٌ ثُمَّ يَتَّبِعُونَهُ مَعَهُمْ الْمُنَافِقُونَ عَلَى جِسْرِ جَهَنَّمَ فِيهِ ‏ ‏كَلَالِيبُ ‏ ‏وَحَسَكٌ ‏ ‏يَأْخُذُونَ مَنْ شَاءَ ثُمَّ يُطْفَأُ نُورُ الْمُنَافِقِينَ ‏ ‏وَيَنْجُو الْمُؤْمِنُونَ ‏ ‏فَتَنْجُو أَوَّلُ ‏ ‏زُمْرَةٍ ‏ ‏وُجُوهُهُمْ كَالْقَمَرِ لَيْلَةَ الْبَدْرِ سَبْعُونَ أَلْفًا لَا يُحَاسَبُونَ ثُمَّ الَّذِينَ يَلُونَهُمْ ‏ ‏كَأَضْوَإِ نَجْمٍ فِي السَّمَاءِ ثُمَّ ذَلِكَ حَتَّى تَحِلَّ ‏ ‏الشَّفَاعَةُ ‏ ‏فَيَشْفَعُونَ ‏ ‏حَتَّى يَخْرُجَ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ مِمَّنْ فِي قَلْبِهِ مِيزَانُ شَعِيرَةٍ فَيُجْعَلَ ‏ ‏بِفِنَاءِ ‏ ‏الْجَنَّةِ وَيَجْعَلُ أَهْلُ الْجَنَّةِ ‏ ‏يُهْرِيقُونَ ‏ ‏عَلَيْهِمْ مِنْ الْمَاءِ حَتَّى يَنْبُتُونَ نَبَاتَ الشَّيْءِ فِي السَّيْلِ وَيَذْهَبُ حَرَقُهُمْ ثُمَّ يَسْأَلُ اللَّهَ ‏ ‏عَزَّ وَجَلَّ حَتَّى يَجْعَلَ لَهُ الدُّنْيَا وَعَشَرَةَ أَمْثَالِهَا ‏","","",""],[14195,14195,"","আমরা মূসা-এর সাথে কথা বলেছি, যখন আমরা আমার সহকর্মীর সাথে কথা বলেছি যে আমি ঈশ্বরের কাছে প্রার্থনা করব, তিনি তার কাছে প্রার্থনা শুনতে পান এবং তিনি বলতেন যে, মা মারা গেছে, আমাকে যেতে হবে। ...আর এই ব্যাপারে কিছু বলা হয়নি... ...যে বলছে রাজা তোমার পয়েন্ট আগুনে দেখেছে. আপনি আমাকে বিশ্বাস করবেন আমাকে বলছেন আমি তাকে খুন করবো। মানে, সে কখনোই বলবে না তুমি এই লোকের কথায় কি বলবে, \"আমি জানি না আপনি স্বর্গ থেকে আপনার কথা বলতে।\" প্রত্যেকটা কালির ওপর এর বিশ্বাসের এবং এর কপটতার মধ্যে কতগুলো ছাপ রয়েছে, তা একেবারে কাছের ।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏عَنْ فَتَّانِي الْقَبْرِ فَقَالَ سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ هَذِهِ الْأُمَّةَ تُبْتَلَى فِي قُبُورِهَا فَإِذَا أُدْخِلَ الْمُؤْمِنُ قَبْرَهُ وَتَوَلَّى عَنْهُ أَصْحَابُهُ جَاءَ مَلَكٌ شَدِيدُ ‏ ‏الِانْتِهَارِ فَيَقُولُ لَهُ مَا كُنْتَ تَقُولُ فِي هَذَا الرَّجُلِ فَيَقُولُ الْمُؤْمِنُ أَقُولُ إِنَّهُ رَسُولُ اللَّهِ وَعَبْدُهُ فَيَقُولُ لَهُ الْمَلَكُ انْظُرْ إِلَى مَقْعَدِكَ الَّذِي كَانَ فِي النَّارِ قَدْ أَنْجَاكَ اللَّهُ مِنْهُ وَأَبْدَلَكَ بِمَقْعَدِكَ الَّذِي ‏ ‏تَرَى مِنْ النَّارِ مَقْعَدَكَ الَّذِي ‏ ‏تَرَى مِنْ الْجَنَّةِ ‏ ‏فَيَرَاهُمَا كِلَاهُمَا فَيَقُولُ الْمُؤْمِنُ دَعُونِي أُبَشِّرْ أَهْلِي فَيُقَالُ لَهُ اسْكُنْ وَأَمَّا الْمُنَافِقُ فَيُقْعَدُ إِذَا تَوَلَّى عَنْهُ أَهْلُهُ فَيُقَالُ لَهُ مَا كُنْتَ تَقُولُ فِي هَذَا الرَّجُلِ فَيَقُولُ لَا أَدْرِي أَقُولُ مَا يَقُولُ النَّاسُ فَيُقَالُ لَهُ لَا دَرَيْتَ هَذَا مَقْعَدُكَ الَّذِي كَانَ لَكَ مِنْ الْجَنَّةِ قَدْ أُبْدِلْتَ مَكَانَهُ مَقْعَدَكَ مِنْ النَّارِ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏فَسَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يُبْعَثُ كُلُّ عَبْدٍ فِي الْقَبْرِ عَلَى مَا مَاتَ الْمُؤْمِنُ عَلَى إِيمَانِهِ وَالْمُنَافِقُ عَلَى نِفَاقِهِ ‏","","",""],[14196,14196,"","আমরা মোশির সঙ্গে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ ‏ ‏جَابِرًا ‏ ‏عَنْ الْجِنَازَةِ قَالَ ‏ ‏قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِجَنَازَةٍ مَرَّتْ وَمَنْ مَعَهُ حَتَّى ‏ ‏تَوَارَتْ ‏","","",""],[14197,14197,"","আমরা মূসা কে বলেছিলাম, আমার প্রিয় বাবার একটা ছেলে আমার বাবার সাথে কথা বলেছি। সে বলল আমি আমার মায়ের পিছু নিয়েছি, যে পরবর্তী ছেলে হবে। যে কিনা বন্দীকে হত্যা করবে, সে বলেছিল আমরা বড় হয়েছি আর তারপর সে বলেছে সে একটা উৎপীড়ক।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَرْجُو أَنْ يَكُونَ مَنْ يَتَّبِعُنِي مِنْ أُمَّتِي يَوْمَ الْقِيَامَةِ رُبُعَ أَهْلِ الْجَنَّةِ قَالَ فَكَبَّرْنَا ثُمَّ قَالَ أَرْجُو أَنْ يَكُونُوا ثُلُثَ النَّاسِ قَالَ فَكَبَّرْنَا ثُمَّ قَالَ أَرْجُو أَنْ يَكُونُوا ‏ ‏الشَّطْرَ ‏","","",""],[14198,14198,"","তিনি বলেছিলেন, নিরাপদ নয়, একজন পণ্ডিত, কোন স্টান্ট নন, কোন স্টান্ট নয়, তিনি নিশ্চিত নন ।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَمْرَضُ مُؤْمِنٌ وَلَا مُؤْمِنَةٌ وَلَا مُسْلِمٌ وَلَا مُسْلِمَةٌ إِلَّا حَطَّ اللَّهُ عَزَّ وَجَلَّ عَنْهُ بِهَا ‏ ‏خَطَايَاهُ ‏","","",""],[14199,14199,"","আমরা সবচেয়ে ছোট ঈশ্বরের বন্ধুর বাবার সঙ্গে আমার বাবার কথা বলেছিলাম । এটা থেকে বের হও।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعَا عِنْدَ مَوْتِهِ بِصَحِيفَةٍ لِيَكْتُبَ فِيهَا كِتَابًا لَا يَضِلُّونَ بَعْدَهُ قَالَ فَخَالَفَ عَلَيْهَا ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏حَتَّى رَفَضَهَا ‏","","",""],[14200,14200,"","আমরা মূসা-এর সাথে কথা বলেছি আমার প্রিয় বাবার সাথে কথা বলেছি যে সে আমাকে বলতে পেরে খুশি হবে যে আমি তার রক্তের বদলে সাক্ষীর সাথে লড়াই করব এবং তার রক্তকে পড়িয়ে দেব।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏أَنَّهُ قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏أَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْضَلُ الْجِهَادِ مَنْ ‏ ‏عُقِرَ ‏ ‏جَوَادُهُ وَأُرِيقَ دَمُهُ فَقَالَ ‏ ‏جَابِرٌ ‏ ‏نَعَمْ ‏","","",""]];
